import spidev
import time
import signal
import sys

# Configuration
SPI_BUS = 0
SPI_DEVICE = 0
ADC_CHANNEL = 0
VREF = 3.3
PPM_PER_VOLT = 200.0
SAFE_PPM = 150
WARNING_PPM = 400
SAMPLE_COUNT = 12
SAMPLE_INTERVAL = 0.5

class GasSensorMonitor:
    def __init__(self, spi_bus, spi_device, adc_channel, vref, ppm_per_volt):
        self.adc_channel = adc_channel
        self.vref = vref
        self.ppm_per_volt = ppm_per_volt
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(spi_bus, spi_device)
            self.spi.max_speed_hz = 1000000
            self.spi.mode = 0
        except OSError as e:
            raise RuntimeError(f"Failed to open SPI bus {spi_bus}, device {spi_device}: {e}")

    def read_adc(self, channel):
        if not 0 <= channel <= 7:
            raise ValueError("ADC channel must be 0-7")
        # MCP3008 single-ended read: start bit, config byte, padding
        cmd = [1, (8 + channel) << 4, 0]
        try:
            resp = self.spi.xfer2(cmd)
        except OSError as e:
            raise RuntimeError(f"SPI transfer failed: {e}")
        # 10-bit result: bits 0-1 of resp[1] are high bits, resp[2] is low byte
        value = ((resp[1] & 0x03) << 8) | resp[2]
        return value

    def to_ppm(self, raw_value):
        voltage = (raw_value / 1023.0) * self.vref
        return voltage * self.ppm_per_volt

    def get_alert_level(self, ppm):
        if ppm < SAFE_PPM:
            return "safe"
        elif ppm < WARNING_PPM:
            return "warning"
        else:
            return "danger"

    def close(self):
        try:
            self.spi.close()
        except Exception:
            pass

def main():
    monitor = None
    def signal_handler(signum, frame):
        print(f"\nReceived signal {signum}, shutting down...")
        if monitor:
            monitor.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        monitor = GasSensorMonitor(SPI_BUS, SPI_DEVICE, ADC_CHANNEL, VREF, PPM_PER_VOLT)
        print("Gas sensor monitoring started. Press Ctrl+C to stop.")
        for i in range(SAMPLE_COUNT):
            try:
                raw = monitor.read_adc(ADC_CHANNEL)
                ppm = monitor.to_ppm(raw)
                level = monitor.get_alert_level(ppm)
                print(f"Sample {i+1}: {raw:4d} -> {ppm:6.1f} ppm -> {level}")
            except RuntimeError as e:
                print(f"Error reading sensor: {e}")
                break
            time.sleep(SAMPLE_INTERVAL)
    except RuntimeError as e:
        print(f"Initialization error: {e}")
    finally:
        if monitor:
            monitor.close()
        print("Resources released. Exiting.")

if __name__ == "__main__":
    main()

