import time
import signal
import sys
import board
import busio
import adafruit_max30102

LOG_FILE = "heart_rate_log.txt"
SAMPLE_INTERVAL = 1.0
WINDOW_SECONDS = 4.0
SAMPLES_PER_WINDOW = int(WINDOW_SECONDS / SAMPLE_INTERVAL)

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _iso_timestamp():
    return time.strftime("%Y-%m-%dT%H:%M:%S")

def _safe_int(value):
    try:
        return int(value)
    except (TypeError, ValueError):
        return value

def _log_reading(fh, part_id, heart_rate, spo2):
    ts = _iso_timestamp()
    line = f"{ts} - Part ID: {_safe_int(part_id)}, Heart Rate: {heart_rate} BPM, SpO2: {spo2} %"
    fh.write(line + "\n")
    fh.flush()
    print(line)

def _compute_heart_rate(ir_samples):
    if len(ir_samples) < 3:
        return None
    peaks = 0
    for i in range(1, len(ir_samples) - 1):
        if ir_samples[i] > ir_samples[i - 1] and ir_samples[i] > ir_samples[i + 1]:
            peaks += 1
    if peaks == 0:
        return None
    return int(60.0 * peaks / WINDOW_SECONDS)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Failed to initialize I2C bus: {e}")
        sys.exit(1)

    try:
        sensor = adafruit_max30102.MAX30102(i2c)
    except Exception as e:
        print(f"Failed to initialize MAX30102 at 0x57: {e}")
        sys.exit(1)

    try:
        with open(LOG_FILE, "a") as fh:
            while _running:
                try:
                    part_id = sensor.part_id
                    ir_samples = []
                    spo2_samples = []
                    for _ in range(SAMPLES_PER_WINDOW):
                        if not _running:
                            break
                        red, ir = sensor.read_sequential()
                        if red is None or ir is None:
                            print("Warning: incomplete FIFO read, skipping sample")
                            time.sleep(SAMPLE_INTERVAL)
                            continue
                        ir_samples.append(ir)
                        # SpO2 is computed from RED vs IR ratio; use IR for peak counting here
                        spo2 = sensor.spo2
                        if spo2 is None:
                            spo2 = -1
                        time.sleep(SAMPLE_INTERVAL)
                    hr = _compute_heart_rate(ir_samples)
                    if hr is None:
                        print("Warning: no heart-rate peaks detected in window")
                    _log_reading(fh, part_id, hr, spo2)
                except Exception as e:
                    print(f"Error during read cycle: {e}")
                    time.sleep(SAMPLE_INTERVAL)
    except OSError as e:
        print(f"File I/O error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        print("Exiting program.")

if __name__ == "__main__":
    main()

