import io
import time
import signal
import sys
import json
import logging
from pathlib import Path

import numpy as np
from PIL import Image
from picamera2 import Picamera2
from gpiozero import OutputDevice

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

CONFIG_FILE = Path('config.json')
running = True

def signal_handler(sig, frame):
    global running
    logger.info('Shutdown signal received.')
    running = False

def load_config():
    try:
        with open(CONFIG_FILE, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        logger.error(f'Configuration file not found: {CONFIG_FILE}')
        return None
    except json.JSONDecodeError as e:
        logger.error(f'Invalid JSON in config file: {e}')
        return None

def init_camera():
    try:
        cam = Picamera2()
        config = cam.create_preview_configuration(main={'size': (224, 224)})
        cam.configure(config)
        cam.start()
        logger.info('Camera initialized successfully.')
        return cam
    except Exception as e:
        logger.error(f'Failed to initialize camera: {e}')
        return None

def capture_image(cam):
    try:
        buf = cam.capture_array()
        if buf is None:
            logger.error('Camera returned None buffer.')
            return None
        img = Image.fromarray(buf).convert('RGB')
        return img
    except Exception as e:
        logger.error(f'Error capturing image: {e}')
        return None

def preprocess_image(img):
    try:
        img = img.resize((224, 224))
        arr = np.array(img, dtype=np.float32) / 255.0
        arr = np.expand_dims(arr, axis=0)
        return arr
    except Exception as e:
        logger.error(f'Error preprocessing image: {e}')
        return None

def indicate_bird(led_pin):
    try:
        led = OutputDevice(led_pin)
        led.on()
        time.sleep(1)
        led.off()
        led.close()
    except Exception as e:
        logger.error(f'Error controlling LED on pin {led_pin}: {e}')

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config()
    if not config:
        sys.exit(1)

    cam = init_camera()
    if not cam:
        sys.exit(1)

    door_control = None
    if 'gpio_door_control' in config:
        try:
            door_control = OutputDevice(config['gpio_door_control'])
            logger.info(f'Feeder door control enabled on GPIO {config["gpio_door_control"]}.')
        except Exception as e:
            logger.error(f'Failed to initialize door control GPIO: {e}')

    try:
        while running:
            img = capture_image(cam)
            if img:
                preprocessed = preprocess_image(img)
                if preprocessed is not None:
                    if door_control:
                        door_control.on()
                    indicate_bird(17)
                    if door_control:
                        door_control.off()
            time.sleep(0.1)
    except Exception as e:
        logger.error(f'Unexpected error in main loop: {e}')
    finally:
        if cam:
            cam.stop()
            logger.info('Camera released.')
        if door_control:
            door_control.close()
            logger.info('Door control GPIO released.')
        logger.info('Program terminated.')

if __name__ == '__main__':
    main()

