import io
import time
import json
import queue
import signal
import logging
import threading
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import FileOutput
import RPi.GPIO as GPIO
from gpiozero import LED

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class CameraHandler:
    def __init__(self, config_file):
        self.config_file = config_file
        self.config = self.load_config()
        self.camera = None
        self.led = None
        self.alert_timer = None
        self.running = True
        self.frame_queue = queue.Queue(maxsize=self.config['max_queue_size'])
        self.setup_signal_handlers()

    def load_config(self):
        try:
            with open(self.config_file, 'r') as f:
                config = json.load(f)
            required_keys = ['resolution', 'framerate', 'max_queue_size', 'gpio_pin', 'alert_duration']
            for key in required_keys:
                if key not in config:
                    raise ValueError(f"Missing required config key: {key}")
            return config
        except FileNotFoundError:
            logging.error(f"Config file not found: {self.config_file}")
            return None
        except json.JSONDecodeError:
            logging.error(f"Invalid JSON in config file: {self.config_file}")
            return None
        except ValueError as e:
            logging.error(f"Invalid config: {e}")
            return None

    def setup_signal_handlers(self):
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

    def signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received, shutting down...")
        self.running = False

    def initialize_camera(self):
        try:
            self.camera = Picamera2()
            resolution = self.config['resolution']
            framerate = self.config['framerate']
            config = self.camera.create_video_configuration(
                main={"size": resolution, "format": "RGB888"},
                controls={"FrameRate": framerate}
            )
            self.camera.configure(config)
            self.camera.start()
            time.sleep(2)
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            self.camera = None

    def capture_frames(self):
        if not self.camera:
            logging.error("Camera not initialized.")
            return
        try:
            while self.running:
                frame = self.camera.capture_array()
                if frame is None:
                    logging.warning("Captured empty frame.")
                    continue
                try:
                    self.frame_queue.put(frame, timeout=1)
                except queue.Full:
                    logging.warning("Frame queue is full. Dropping frame.")
                time.sleep(0.1)
        except Exception as e:
            logging.error(f"Error capturing frames: {e}")

    def trigger_alert(self):
        try:
            if self.led:
                self.led.on()
                self.alert_timer = threading.Timer(self.config['alert_duration'], self.led.off)
                self.alert_timer.start()
        except Exception as e:
            logging.error(f"Error triggering alert: {e}")

    def initialize_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.config['gpio_pin'], GPIO.OUT, initial=GPIO.LOW)
            self.led = LED(self.config['gpio_pin'])
            logging.info("GPIO initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing GPIO: {e}")
            self.led = None

    def cleanup(self):
        logging.info("Cleaning up resources...")
        if self.alert_timer and self.alert_timer.is_alive():
            self.alert_timer.cancel()
        if self.led:
            self.led.off()
            self.led.close()
        if self.camera:
            self.camera.stop()
            self.camera.close()
        GPIO.cleanup()
        logging.info("Cleanup complete.")

    def run(self):
        if not self.config:
            logging.error("Failed to load configuration. Exiting.")
            return
        self.initialize_camera()
        self.initialize_gpio()
        capture_thread = threading.Thread(target=self.capture_frames, daemon=True)
        capture_thread.start()
        try:
            while self.running:
                time.sleep(1)
        except KeyboardInterrupt:
            logging.info("Keyboard interrupt received.")
        finally:
            self.cleanup()

if __name__ == "__main__":
    camera_handler = CameraHandler("config.json")
    camera_handler.run()

