import atexit
import signal
import sys
import time
import logging
from threading import Thread, Lock

from flask import Flask, render_template, Response, request

try:
    from picamera2 import Picamera2
except ImportError:
    print("picamera2 is not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)

from config import Config  # user-provided
from mail_config import send_email  # user-provided

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

app = Flask(__name__)
config = Config()
picam2 = None
frame_lock = Lock()
last_email_time = 0.0
shutdown_requested = False


class Camera:
    """Wrapper around picamera2 for JPEG streaming and object detection."""

    def __init__(self):
        global picam2
        try:
            picam2 = Picamera2()
            video_config = picam2.create_video_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                transform=Transform(vflip=True)  # vertical flip via transform
            )
            picam2.configure(video_config)
            picam2.start()
            logger.info("Camera initialized successfully (640x480, vflip=True).")
        except Exception as e:
            logger.error(f"Failed to initialize camera: {e}")
            raise

    def get_frame(self):
        """Return the latest JPEG-encoded frame bytes."""
        global picam2
        if picam2 is None:
            return b""
        try:
            frame = picam2.capture_array()
            if frame is None:
                logger.warning("capture_array returned None.")
                return b""
            import cv2
            ok, encoded = cv2.imencode('.jpg', frame)
            if not ok:
                logger.warning("JPEG encoding failed.")
                return b""
            return encoded.tobytes()
        except Exception as e:
            logger.error(f"Error capturing frame: {e}")
            return b""

    def get_object(self, classifier):
        """Return (jpeg_bytes, bool_detected) from a classifier."""
        try:
            frame = self.get_frame()
            if not frame:
                return b"", False
            detected = classifier.classify_image(frame)
            return frame, detected
        except Exception as e:
            logger.error(f"Error in get_object: {e}")
            return b"", False

    def get_object_with_basic_motion_detection(self):
        """Return (jpeg_bytes, bool_detected) with basic motion heuristic."""
        try:
            frame = self.get_frame()
            if not frame:
                return b"", False
            # Simple motion heuristic: compare current frame to previous
            # (not implemented here; placeholder for user-provided motion logic)
            return frame, False
        except Exception as e:
            logger.error(f"Error in get_object_with_basic_motion_detection: {e}")
            return b"", False

    def close(self):
        """Stop the camera and release resources."""
        global picam2
        if picam2 is not None:
            try:
                picam2.stop()
                logger.info("Camera stopped.")
            except Exception as e:
                logger.error(f"Error stopping camera: {e}")
            finally:
                picam2 = None


def check_for_objects():
    """Background thread: periodically check for objects and send emails."""
    global last_email_time, shutdown_requested
    while not shutdown_requested:
        if config.classifier_name == 'motion_detector':
            frame, detected = camera.get_object_with_basic_motion_detection()
        else:
            classifier = config.classifier
            frame, detected = camera.get_object(classifier)

        if detected and config.send_email_notifications:
            now = time.time()
            if now - last_email_time >= config.email_send_interval:
                try:
                    send_email(frame, config)
                    last_email_time = now
                    logger.info("Email notification sent.")
                except Exception as e:
                    logger.error(f"Error sending email: {e}")

        time.sleep(0.1)


@app.route('/', methods=['GET', 'POST'])
def index():
    """Handle configuration form and render index.html."""
    if request.method == 'POST':
        try:
            config.set_classifier(request.form['classifier'])
            config.live_preview = (request.form.get('live_preview', 'off') == 'on')
            config.send_email_notifications = (request.form.get('send_email_notifications', 'off') == 'on')
            config.recipient_address = request.form['recipient_address']
            config.email_send_interval = float(request.form['email_send_interval'])
            logger.info("Configuration updated via form.")
        except Exception as e:
            logger.error(f"Error updating configuration: {e}")
    return render_template('index.html', classifiers=config.classifierNameLocationDict, config=config)


def gen(camera):
    """Generator yielding JPEG frames for the video feed."""
    while not shutdown_requested:
        try:
            frame, _ = camera.get_object_with_basic_motion_detection()
            if frame:
                yield (b'--frame\r\n'
                       b'Content-Type: image/jpeg\r\n\r\n' + frame + b'\r\n\r\n')
            else:
                time.sleep(0.05)
        except Exception as e:
            logger.error(f"Error in gen: {e}")
            time.sleep(0.1)


@app.route('/video_feed')
def video_feed():
    return Response(gen(camera), mimetype='multipart/x-mixed-replace; boundary=frame')


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global shutdown_requested
    logger.info(f"Received signal {signum}, shutting down...")
    shutdown_requested = True


def cleanup():
    """Release camera and other resources on exit."""
    global camera
    if camera is not None:
        camera.close()
    logger.info("Cleanup complete.")


if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        camera = Camera()
    except Exception:
        print("Camera initialization failed. Exiting.", file=sys.stderr)
        sys.exit(1)

    atexit.register(cleanup)

    object_detection_thread = Thread(target=check_for_objects, daemon=True)
    object_detection_thread.start()

    try:
        app.run(host='0.0.0.0', port=5000, debug=False, threaded=True)
    except Exception as e:
        logger.error(f"Flask app error: {e}")
    finally:
        shutdown_requested = True
        object_detection_thread.join(timeout=2)
        cleanup()

