import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

cap = None
serial_port = None

try:
    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        raise IOError("Cannot open webcam 0")
    ret, frame = cap.read()
    if not ret or frame is None:
        raise IOError("Cannot read initial frame from webcam 0")

    # Validate serial port availability
    available_ports = [p.device for p in serial.tools.list_ports.comports()]
    preferred_port = "/dev/ttyACM0"
    if preferred_port in available_ports:
        try:
            serial_port = serial.Serial(preferred_port, 9600, timeout=1)
        except serial.SerialException as e:
            print(f"Warning: could not open {preferred_port}: {e}")
            serial_port = None
    else:
        if available_ports:
            print(f"Warning: {preferred_port} not found; using {available_ports[0]}")
            try:
                serial_port = serial.Serial(available_ports[0], 9600, timeout=1)
            except serial.SerialException as e:
                print(f"Warning: could not open {available_ports[0]}: {e}")
                serial_port = None
        else:
            print("Warning: no serial ports available; running in serial-disabled mode")

    min_HSV = np.array([0, 0, 0], dtype=np.uint8)
    max_HSV = np.array([179, 255, 255], dtype=np.uint8)
    tracking = False

    while running:
        ret, frame = cap.read()
        if not ret or frame is None:
            print("Warning: frame read failed; exiting loop")
            break

        h_frame, w_frame = frame.shape[:2]
        cx, cy = w_frame // 2, h_frame // 2
        half_extent = 50
        x1, y1 = max(0, cx - half_extent), max(0, cy - half_extent)
        x2, y2 = min(w_frame, cx + half_extent), min(h_frame, cy + half_extent)
        roi = frame[y1:y2, x1:x2]

        hsv_roi = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
        if tracking:
            mask = cv2.inRange(hsv_roi, min_HSV, max_HSV)
            contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            for cnt in contours:
                if cv2.contourArea(cnt) > 500:
                    x, y, w_cnt, h_cnt = cv2.boundingRect(cnt)
                    cv2.rectangle(frame, (x + x1, y + y1), (x + x1 + w_cnt, y + y1 + h_cnt), (255, 0, 0), 2)
                    ball_x = x + w_cnt // 2
                    ball_y = y + h_cnt // 2
                    if ball_x > cx + half_extent and ball_y > cy + half_extent:
                        pos_str = "1"
                    elif ball_x > cx + half_extent and ball_y < cy - half_extent:
                        pos_str = "2"
                    elif ball_x < cx - half_extent and ball_y > cy + half_extent:
                        pos_str = "3"
                    elif ball_x < cx - half_extent and ball_y < cy - half_extent:
                        pos_str = "4"
                    else:
                        pos_str = "5"
                    if serial_port is not None:
                        try:
                            serial_port.write(pos_str.encode('utf-8'))
                        except serial.SerialException as e:
                            print(f"Serial write error: {e}")
                    cv2.putText(frame, pos_str, (x + x1, y + y1 - 10), cv2.FONT_HERSHEY_SIMPLEX, 0.9, (0, 255, 0), 2)

        cv2.imshow("Frame", frame)
        key = cv2.waitKey(1) & 0xFF
        if key == ord('s'):
            hsv_roi = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
            min_HSV = np.array([hsv_roi[:, :, 0].min(), hsv_roi[:, :, 1].min(), hsv_roi[:, :, 2].min()], dtype=np.uint8)
            max_HSV = np.array([hsv_roi[:, :, 0].max(), hsv_roi[:, :, 1].max(), hsv_roi[:, :, 2].max()], dtype=np.uint8)
            tracking = True
            print(f"Tracking enabled: min_HSV={min_HSV}, max_HSV={max_HSV}")
        elif key == ord('o'):
            tracking = False
            print("Tracking disabled")
        elif key == 27:
            break

except Exception as e:
    print(f"Error: {e}")

finally:
    if cap is not None:
        cap.release()
    if serial_port is not None and serial_port.is_open:
        serial_port.close()
    cv2.destroyAllWindows()

