import cv2
import numpy as np
import serial
import time
import signal
import sys
import RPi.GPIO as GPIO
from picamera2 import Picamera2

# Constants
CAMERA_WIDTH = 160
CAMERA_HEIGHT = 120
CAMERA_FRAMERATE = 16
SERIAL_PORT = '/dev/ttyACM0'
SERIAL_BAUDRATE = 115200
SERVO_PIN_1 = 7
SERVO_PIN_2 = 13
SERVO_FREQUENCY = 50
SERVO_CENTER_DUTY = 7.0
SERVO_INCREMENT = 0.1
MAX_SERVO_DUTY = 12.0
MIN_SERVO_DUTY = 2.0
MIN_TARGET_AREA = 20
MAX_TARGET_AREA = 10000
SMALL_TARGET_AREA = 100
LARGE_TARGET_AREA = 2000
MEDIUM_TARGET_AREA = 500

# Global state
ard = None
picam2 = None
servo1_duty = SERVO_CENTER_DUTY
servo2_duty = SERVO_CENTER_DUTY
running = True

def signal_handler(sig, frame):
    global running
    running = False

def cleanup():
    global ard, picam2
    if ard is not None and ard.is_open:
        try:
            ard.write(b'h')
            ard.close()
        except Exception:
            pass
    if picam2 is not None:
        try:
            picam2.stop()
        except Exception:
            pass
    GPIO.cleanup()

def init_serial():
    global ard
    try:
        ard = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=1)
        time.sleep(2)
        return True
    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}")
        return False

def init_gpio():
    GPIO.setmode(GPIO.BOARD)
    GPIO.setup(SERVO_PIN_1, GPIO.OUT)
    GPIO.setup(SERVO_PIN_2, GPIO.OUT)
    pwm1 = GPIO.PWM(SERVO_PIN_1, SERVO_FREQUENCY)
    pwm2 = GPIO.PWM(SERVO_PIN_2, SERVO_FREQUENCY)
    pwm1.start(servo1_duty)
    pwm2.start(servo2_duty)
    return pwm1, pwm2

def init_camera():
    global picam2
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": (CAMERA_WIDTH, CAMERA_HEIGHT), "format": "BGR888"},
            controls={"FrameRate": CAMERA_FRAMERATE}
        )
        picam2.configure(config)
        picam2.start()
        time.sleep(0.5)
        return True
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return False

def segment_red(frame):
    hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    mask1 = cv2.inRange(hsv, np.array([160, 160, 10]), np.array([190, 255, 255]))
    ycr = cv2.cvtColor(frame, cv2.COLOR_BGR2YCrCb)
    mask2 = cv2.inRange(ycr, np.array((0., 165., 0.)), np.array((255., 255., 255.)))
    mask = mask1 | mask2
    mask = cv2.erode(mask, np.ones((3, 3), np.uint8))
    mask = cv2.dilate(mask, np.ones((8, 8), np.uint8))
    return mask

def find_blob(mask):
    contours, _ = cv2.findContours(mask, cv2.RETR_CCOMP, cv2.CHAIN_APPROX_SIMPLE)
    largest = (0, 0, 2, 2)
    largest_area = 0
    for c in contours:
        area = cv2.contourArea(c)
        if area > largest_area:
            largest_area = area
            largest = cv2.boundingRect(c)
    return largest, largest_area

def control_servos(x, pwm1, pwm2):
    global servo1_duty, servo2_duty
    if x < CAMERA_WIDTH // 3:
        cmd = 'a'
    elif x < 2 * CAMERA_WIDTH // 3:
        cmd = 'g'
    else:
        cmd = 'b'
    pwm1.ChangeDutyCycle(servo1_duty)
    pwm2.ChangeDutyCycle(servo2_duty)
    if ard is not None and ard.is_open:
        try:
            ard.write(cmd.encode())
        except Exception:
            pass

def main():
    global running, servo1_duty, servo2_duty
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    if not init_serial():
        print("Serial init failed; continuing without Arduino.")
    pwm1, pwm2 = init_gpio()
    if not init_camera():
        cleanup()
        sys.exit(1)
    try:
        while running:
            frame = picam2.capture_array()
            if frame is None:
                continue
            mask = segment_red(frame)
            (x, y, w, h), area = find_blob(mask)
            if MIN_TARGET_AREA < area < MAX_TARGET_AREA:
                cx = x + w // 2
                cy = y + h // 2
                if SMALL_TARGET_AREA < area < MEDIUM_TARGET_AREA:
                    cmd = 'j'
                elif area > LARGE_TARGET_AREA:
                    cmd = 'k'
                else:
                    cmd = 'f'
                control_servos(cx, pwm1, pwm2)
                if ard is not None and ard.is_open:
                    try:
                        ard.write(cmd.encode())
                    except Exception:
                        pass
            elif area < MIN_TARGET_AREA:
                if ard is not None and ard.is_open:
                    try:
                        ard.write(b'h')
                    except Exception:
                        pass
                servo2_duty += SERVO_INCREMENT
                if servo2_duty > MAX_SERVO_DUTY:
                    servo2_duty = SERVO_CENTER_DUTY
                pwm2.ChangeDutyCycle(servo2_duty)
            else:
                if ard is not None and ard.is_open:
                    try:
                        ard.write(b'h')
                    except Exception:
                        pass
    except Exception as e:
        print(f"Error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

