            raise ValueError("Config must be a JSON object")
        if "sensors" not in config or not isinstance(config["sensors"], list):
            raise ValueError("'sensors' list required")
        for s in config["sensors"]:
            if not all(k in s for k in ("trigger_pin", "echo_pin", "offset", "max_distance")):
                raise ValueError("Each sensor must have trigger_pin, echo_pin, offset, max_distance")
    except (json.JSONDecodeError, ValueError, OSError) as e:
        logger.error(f"Config load error: {e}; using defaults")
        config = dict(DEFAULT_CONFIG)


def setup_logging():
    global logger
    logger = logging.getLogger("water_level")
    logger.setLevel(logging.INFO)
    fmt = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
    fh = logging.FileHandler(config.get("log_file", "water_level.log"))
    fh.setFormatter(fmt)
    logger.addHandler(fh)
    sh = logging.StreamHandler()
    sh.setFormatter(fmt)
    logger.addHandler(sh)


def init_gpio():
    global triggers, echos
    if OutputDevice is None or InputDevice is None:
        logger.error("gpiozero not available; running in dry-run mode")
        return True
    for s in config["sensors"]:
        try:
            t = OutputDevice(s["trigger_pin"])
            e = InputDevice(s["echo_pin"])
            triggers.append(t)
            echos.append(e)
        except Exception as e:
            logger.error(f"GPIO init failed for trigger={s['trigger_pin']}, echo={s['echo_pin']}: {e}")
            return False
    return True


def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    try:
        t = triggers[triggers.index(next((t for t in triggers if t.pin.number == trigger_pin), None))]
        e = echos[echos.index(next((e for e in echos if e.pin.number == echo_pin), None))]
    except Exception:
        logger.error(f"Invalid GPIO pin for trigger={trigger_pin}, echo={echo_pin}")
        return None
    try:
        t.off()
        time.sleep(50e-6)
        t.on()
        time.sleep(TRIGGER_PULSE_US)
        t.off()
        deadline = time.time() + TIMEOUT
        while e.value == 0:
            if time.time() > deadline:
                logger.warning(f"Timeout waiting for echo rising edge on trigger={trigger_pin}, echo={echo_pin}")
                return None
        pulse_start = time.time()
        deadline = time.time() + TIMEOUT
        while e.value == 1:
            if time.time() > deadline:
                logger.warning(f"Timeout waiting for echo falling edge on trigger={trigger_pin}, echo={echo_pin}")
                return None
        pulse_end = time.time()
        pulse_duration = pulse_end - pulse_start
        distance = (pulse_duration * SPEED_OF_SOUND) / 2.0
        distance -= offset
        if distance < 0 or distance > max_distance:
            logger.warning(f"Distance {distance:.2f} out of range [0, {max_distance}] on trigger={trigger_pin}, echo={echo_pin}")
            return None
        return distance
    except Exception as e:
        logger.error(f"Error measuring distance on trigger={trigger_pin}, echo={echo_pin}: {e}")
        return None


def get_median_water_level():
    distances = []
    for s in config["sensors"]:
        for _ in range(SENSOR_READINGS):
            d = measure_distance(s["trigger_pin"], s["echo_pin"], s["offset"], s["max_distance"])
            if d is not None:
                distances.append(d)
                break
    if not distances:
        logger.error("No valid sensor readings")
        return None
    return statistics.median(distances)


def check_alerts(water_level):
    low = config["alert_threshold_low"]
    high = config["alert_threshold_high"]
    repeat_delay = config["alert_repeat_delay"]
    if water_level is None:
        return
    if water_level < low:
        if water_level < low - 5:
            logger.warning(f"Low water level: {water_level:.2f}")
        if (water_level < low and
                (last_alerts.get("low", 0) == 0 or
                 (time.time() - last_alerts["low"]) > repeat_delay)):
            logger.warning(f"ALERT: Low water level: {water_level:.2f}")
            last_alerts["low"] = time.time()
    elif water_level > high:
        if water_level > high + 5:
            logger.warning(f"High water level: {water_level:.2f}")
        if (water_level > high and
                (last_alerts.get("high", 0) == 0 or
                 (time.time() - last_alerts["high"]) > repeat_delay)):
            logger.warning(f"ALERT: High water level: {water_level:.2f}")
            last_alerts["high"] = time.time()


def cleanup():
    global triggers, echos
    for t in triggers:
        try:
            t.close()
        except Exception:
            pass
    for e in echos:
        try:
            e.close()
        except Exception:
            pass
    triggers.clear()
    echos.clear()
    logger.info("GPIO cleanup complete")


def main():
    global running, config
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    setup_logging()
    load_config()
    if not init_gpio():
        logger.error("GPIO initialization failed; exiting")
        cleanup()
        sys.exit(0)
    logger.info("Water level monitoring started")
    try:
        while running:
            try:
                water_level = get_median_water_level()
                if water_level is not None:
                    logger.info(f"Water level: {water_level:.2f}")
                    check_alerts(water_level)
                else:
                    logger.warning("No valid water level reading")
            except Exception as e:
                logger.error(f"Unexpected error in main loop: {e}")
            for _ in range(POLL_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logger.error(f"Fatal error: {e}")
    finally:
        cleanup()
        logger.info("Program exiting")


if __name__ == "__main__":
    main()

