        GPIO_AVAILABLE = False
else:
    logging.info("Simulated GPIO mode.")

# Initialize DHT11 sensor
dht_device = None
if DHT_AVAILABLE:
    try:
        dht_device = adafruit_dht.DHT11(board.D4)
        logging.info("DHT11 sensor initialized.")
    except Exception as e:
        logging.error(f"Failed to initialize DHT11 sensor: {e}. Using simulated temperature.")
        DHT_AVAILABLE = False
else:
    logging.info("Simulated temperature mode.")

# Initialize camera
picam2 = None
if CAMERA_AVAILABLE:
    try:
        picam2 = Picamera2()
        picam2.configure(picam2.create_still_configuration(main={"size": (640, 480)}))
        picam2.start()
        logging.info("Camera initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}. Camera functionality disabled.")
        CAMERA_AVAILABLE = False
else:
    logging.info("Camera functionality disabled.")

def cleanup(signum=None, frame=None):
    """Clean up resources on exit."""
    global running
    running = False
    logging.info("Cleaning up resources...")
    if GPIO_AVAILABLE:
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error(f"Error cleaning up GPIO: {e}")
    if picam2 is not None:
        try:
            picam2.stop()
            logging.info("Camera stopped.")
        except Exception as e:
            logging.error(f"Error stopping camera: {e}")
    if dht_device is not None:
        try:
            dht_device.exit()
            logging.info("DHT11 sensor exited.")
        except Exception as e:
            logging.error(f"Error exiting DHT11 sensor: {e}")
    logging.info("Cleanup complete. Exiting.")
    sys.exit(0)

