    """Turns the lights on."""
    global lights_on
    if GPIO_AVAILABLE:
        try:
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
            lights_on = True
            logging.info("Lights turned on.")
        except Exception as e:
            logging.error(f"Error turning on lights: {e}")
    else:
        logging.info("Simulated: Lights turned on.")

def turn_lights_off():
    """Turns the lights off."""
    global lights_on
    if GPIO_AVAILABLE:
        try:
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            lights_on = False
            logging.info("Lights turned off.")
        except Exception as e:
            logging.error(f"Error turning off lights: {e}")
    else:
        logging.info("Simulated: Lights turned off.")

