    """Reads the temperature from the DHT11 sensor."""
    if DHT_AVAILABLE and dht_device is not None:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                logging.info(f"Temperature: {temperature:.1f}°C")
                return temperature
            else:
                logging.warning("DHT11 returned None temperature.")
                return None
        except RuntimeError as e:
            logging.warning(f"DHT11 read error (checksum or timeout): {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error reading DHT11: {e}")
            return None
    else:
        # Simulate temperature between 15 and 35 degrees Celsius
        temperature = random.uniform(15, 35)
        logging.info(f"Simulated Temperature: {temperature:.1f}°C")
        return temperature

def take_picture():
    """Takes a picture using the Raspberry Pi camera."""
    if not CAMERA_AVAILABLE:
        logging.warning("Camera not available. Cannot take picture.")
        return
    try:
        os.makedirs(IMAGE_DIR, exist_ok=True)
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        image_path = os.path.join(IMAGE_DIR, f"greenhouse_{timestamp}.jpg")
        picam2.capture_file(image_path)
        logging.info(f"Picture saved to {image_path}")
    except Exception as e:
        logging.error(f"Error taking picture: {e}")

def listen_for_commands():
    """Listens for voice commands and executes actions."""
    global running
    recognizer = sr.Recognizer()
    try:
        with sr.Microphone() as source:
            recognizer.adjust_for_ambient_noise(source)
            logging.info("Listening for commands...")
            while running:
                try:
                    audio = recognizer.listen(source, timeout=5, phrase_time_limit=5)
                    try:
                        command = recognizer.recognize_google(audio).lower()
                        logging.info(f"Recognized command: {command}")
                        if WAKE_WORD in command:
                            command = command.replace(WAKE_WORD, "").strip()
                            if "turn on the lights" in command:
                                turn_lights_on()
                            elif "turn off the lights" in command:
                                turn_lights_off()
                            elif "what is the temperature" in command:
                                temperature = read_temperature()
                                if temperature is not None:
                                    print(f"The temperature is {temperature:.1f} degrees Celsius.")
                                else:
                                    print("Could not read temperature.")
                            elif "take a picture" in command:
                                take_picture()
                            else:
                                print("I didn't understand that command.")
                        else:
                            logging.info("Command did not contain wake word.")
                    except sr.UnknownValueError:
                        logging.warning("Could not understand audio.")
                    except sr.RequestError as e:
                        logging.error(f"Could not request results from Google Web Speech API: {e}")
                except sr.WaitTimeoutError:
                    pass
    except Exception as e:
        logging.error(f"Error setting up microphone: {e}")

def main():
    """Main function to start the greenhouse control system."""
    logging.info("Starting greenhouse control system...")
    listen_for_commands()

if __name__ == "__main__":
    main()

