import RPi.GPIO as GPIO
import time
import datetime
import os
import argparse
import csv
import sys
import signal
from picamera2 import Picamera2

# Global resources for cleanup
_gpio_initialized = False
_camera = None
_running = True

def signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio(gpio_pins):
    global _gpio_initialized
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in gpio_pins:
        try:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        except Exception as e:
            print(f"Error setting up GPIO pin {pin}: {e}", file=sys.stderr)
            raise
    _gpio_initialized = True

def calibrate_sensors(gpio_pins, interval, calibrate_duration):
    print("Calibrating sensors...")
    start_time = time.time()
    readings = {pin: [] for pin in gpio_pins}
    while time.time() - start_time < calibrate_duration:
        for pin in gpio_pins:
            try:
                readings[pin].append(GPIO.input(pin))
            except Exception as e:
                print(f"Error reading GPIO pin {pin} during calibration: {e}", file=sys.stderr)
                readings[pin].append(0)
        time.sleep(interval)
    baselines = {}
    for pin in gpio_pins:
        if not readings[pin]:
            baselines[pin] = 0.0
        else:
            baselines[pin] = sum(readings[pin]) / len(readings[pin])
    print("Calibration complete.")
    return baselines

def get_sensor_data(gpio_pins, baselines):
    data = {}
    for pin in gpio_pins:
        try:
            data[pin] = GPIO.input(pin)
        except Exception as e:
            print(f"Error reading GPIO pin {pin}: {e}", file=sys.stderr)
            data[pin] = 0
    active_sensors = 0
    for pin in gpio_pins:
        if data[pin] == 1:
            active_sensors += 1
    return data, active_sensors

def log_data(log_file, timestamp, sensor_data, active_sensors):
    try:
        with open(log_file, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp, sensor_data[16], sensor_data[17], sensor_data[22], active_sensors])
            csvfile.flush()
    except Exception as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def capture_image(camera, timestamp):
    if camera is None:
        print("Camera not available, skipping image capture.")
        return
    try:
        os.makedirs("images", exist_ok=True)
        filename = f"images/{timestamp}.jpg"
        camera.capture_file(filename)
        print(f"Image captured: {filename}")
    except Exception as e:
        print(f"Error capturing image: {e}", file=sys.stderr)

def cleanup():
    global _gpio_initialized, _camera
    if _gpio_initialized:
        GPIO.cleanup()
        _gpio_initialized = False
    if _camera is not None:
        try:
            _camera.close()
        except Exception:
            pass
        _camera = None

def main():
    global _camera, _running
    parser = argparse.ArgumentParser(description="Vibration Monitoring System")
    parser.add_argument("-g", "--gpio", nargs=3, type=int, required=True, help="BCM GPIO pin numbers for sensors")
    parser.add_argument("-l", "--log_file", type=str, required=True, help="Path to the log file")
    parser.add_argument("-i", "--interval", type=float, required=True, help="Sampling interval in seconds")
    parser.add_argument("-c", "--calibrate", type=int, required=True, help="Calibration duration in seconds")
    parser.add_argument("-p", "--picture_interval", type=int, required=True, help="Time between image captures in seconds")
    args = parser.parse_args()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        setup_gpio(args.gpio)
    except Exception:
        print("Failed to initialize GPIO. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        _camera = Picamera2()
        _camera.configure(_camera.create_still_configuration(main={"size": (640, 480)}))
        _camera.start()
        print("Camera initialized successfully.")
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        _camera = None

    try:
        with open(args.log_file, 'w', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(["Timestamp", "Sensor1", "Sensor2", "Sensor3", "ActiveSensors"])
            csvfile.flush()
    except Exception as e:
        print(f"Error creating log file: {e}", file=sys.stderr)
        sys.exit(1)

    baselines = calibrate_sensors(args.gpio, args.interval, args.calibrate)
    thresholds = {pin: baseline + 0.2 for pin, baseline in baselines.items()}

    last_image_time = 0
    try:
        while _running:
            sensor_data, active_sensors = get_sensor_data(args.gpio, baselines)
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")
            log_data(args.log_file, timestamp, sensor_data, active_sensors)
            print(f"Timestamp: {timestamp}, Sensor1: {sensor_data[16]}, Sensor2: {sensor_data[17]}, Sensor3: {sensor_data[22]}, ActiveSensors: {active_sensors}")

            if time.time() - last_image_time >= args.picture_interval:
                capture_image(_camera, timestamp)
                last_image_time = time.time()

            time.sleep(args.interval)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

