import signal
import sys
import time

try:
    from gpiozero import Button, OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    inputs = []
    outputs = []
    try:
        for pin in INPUT_PINS:
            try:
                inputs.append(Button(pin, pull_up=True, bounce_time=None))
            except (GPIODeviceError, GPIOZeroError) as exc:
                print(f"Error: failed to initialize input GPIO {pin}: {exc}", file=sys.stderr)
                sys.exit(1)
        for pin in OUTPUT_PINS:
            try:
                outputs.append(OutputDevice(pin, active_high=True, initial_value=False))
            except (GPIODeviceError, GPIOZeroError) as exc:
                print(f"Error: failed to initialize output GPIO {pin}: {exc}", file=sys.stderr)
                sys.exit(1)
    except Exception as exc:
        print(f"Error: GPIO initialization failed: {exc}", file=sys.stderr)
        sys.exit(1)

    output_24_state = False
    try:
        while _running:
            try:
                if inputs[0].is_active:
                    outputs[0].on()
                elif inputs[1].is_active:
                    outputs[0].off()
                elif inputs[2].is_active:
                    output_24_state = not output_24_state
                    outputs[1].toggle()
            except (GPIODeviceError, GPIOZeroError) as exc:
                print(f"Warning: GPIO read/write error: {exc}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)
    finally:
        for dev in inputs + outputs:
            try:
                dev.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

