#!/usr/bin/env python3
"""
Motion-activated security camera using picamera2 and OpenCV.
Records 5-second H.264 clips when motion is detected above a threshold.
Deletes oldest clips when total size exceeds 1 GB.
"""

import argparse
import datetime
import os
import signal
import sys
import time
from pathlib import Path

import cv2
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FileOutput

# Global flag for graceful shutdown
running = True


def signal_handler(sig, frame):
    """Handle Ctrl+C gracefully."""
    global running
    print("\nShutdown signal received. Cleaning up...")
    running = False


def parse_args():
    parser = argparse.ArgumentParser(
        description="Raspberry Pi Motion-Activated Security Camera"
    )
    parser.add_argument(
        "--threshold", type=int, default=5,
        help="Motion detection threshold (brightness difference). Default: 5"
    )
    parser.add_argument(
        "--duration", type=int, default=5,
        help="Recording duration in seconds. Default: 5"
    )
    parser.add_argument(
        "--max_size", type=int, default=1024,
        help="Maximum total clip size in MB. Default: 1024 (1 GB)"
    )
    return parser.parse_args()


def init_camera():
    """Initialize picamera2 with 320x240 @ 15 fps. Returns Picamera2 or None."""
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": (320, 240), "format": "RGB888"},
            controls={"FrameRate": 15}
        )
        picam2.configure(config)
        picam2.start()
        # Allow auto-exposure to settle
        time.sleep(2)
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None


def ensure_directory(path: str) -> bool:
    """Create directory if it doesn't exist. Returns True on success."""
    try:
        Path(path).mkdir(parents=True, exist_ok=True)
        return True
    except PermissionError:
        print(f"Permission denied creating directory: {path}")
        return False
    except OSError as e:
        print(f"Error creating directory {path}: {e}")
        return False


def capture_frame(picam2):
    """Capture a frame as a numpy array (RGB). Returns None on failure."""
    try:
        frame = picam2.capture_array()
        if frame is None or frame.size == 0:
            print("Warning: captured empty frame")
            return None
        return frame
    except Exception as e:
        print(f"Error capturing frame: {e}")
        return None


def calculate_average_brightness(frame):
    """Return average brightness across all color channels."""
    try:
        # Convert to grayscale for more accurate brightness
        gray = cv2.cvtColor(frame, cv2.COLOR_RGB2GRAY)
        return float(np.mean(gray))
    except Exception as e:
        print(f"Error calculating brightness: {e}")
        return 0.0


def record_clip(picam2, output_path: str, duration: int):
    """Record a H.264 video clip of given duration. Returns True on success."""
    try:
        encoder = H264Encoder(bitrate=1000000)
        output = FileOutput(output_path)
        picam2.start_recording(encoder, output)
        time.sleep(duration)
        picam2.stop_recording()
        print(f"Recorded clip: {output_path}")
        return True
    except Exception as e:
        print(f"Error recording clip: {e}")
        # Ensure recording is stopped even if exception occurs mid-record
        try:
            picam2.stop_recording()
        except Exception:
            pass
        return False


def manage_storage(path: str, max_size_mb: int):
    """Delete oldest clips if total size exceeds max_size_mb."""
    max_size_bytes = max_size_mb * 1024 * 1024
    try:
        files = [
            (f, os.path.getmtime(f), os.path.getsize(f))
            for f in Path(path).glob("*.h264")
        ]
        if not files:
            return
        total_size = sum(s for _, _, s in files)
        if total_size <= max_size_bytes:
            return
        # Sort by modification time (oldest first)
        files.sort(key=lambda x: x[1])
        for f_path, _, f_size in files:
            if total_size <= max_size_bytes:
                break
            try:
                os.remove(f_path)
                total_size -= f_size
                print(f"Deleted old clip: {f_path}")
            except OSError as e:
                print(f"Error deleting {f_path}: {e}")
    except Exception as e:
        print(f"Error managing storage: {e}")


def main():
    global running
    args = parse_args()
    threshold = args.threshold
    duration = args.duration
    max_size_mb = args.max_size

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Ensure output directory exists
    if not ensure_directory("/home/pi/security_footage"):
        sys.exit(1)

    picam2 = init_camera()
    if picam2 is None:
        sys.exit(1)

    previous_brightness = 0.0

    try:
        while running:
            frame = capture_frame(picam2)
            if frame is None:
                time.sleep(2)
                continue

            current_brightness = calculate_average_brightness(frame)
            brightness_change = abs(current_brightness - previous_brightness)

            if brightness_change > threshold:
                timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
                output_path = f"/home/pi/security_footage/{timestamp}.h264"
                if record_clip(picam2, output_path, duration):
                    manage_storage("/home/pi/security_footage", max_size_mb)
                # Reset previous brightness to avoid immediate re-trigger
                previous_brightness = current_brightness

            previous_brightness = current_brightness
            time.sleep(2)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        try:
            picam2.stop_recording()
        except Exception:
            pass
        try:
            picam2.close()
        except Exception:
            pass
        print("Camera released. Exiting.")


if __name__ == "__main__":
    main()

