import serial
import sys
import signal

BLUETOOTH_PORT = "/dev/rfcomm4"
BAUD_RATE = 38400
TRANSMIT_PREFIX = "X"

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def open_bluetooth_connection(port, baud):
    try:
        conn = serial.Serial(
            port=port,
            baudrate=baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            xonxoff=False,
            rtscts=False,
            dsrdtr=False,
            timeout=1.0,
        )
        if not conn.is_open:
            raise serial.SerialException(f"Failed to open {port}")
        print(f"Bluetooth connection established on {port} at {baud} baud.")
        return conn
    except serial.SerialException as e:
        print(f"Error opening Bluetooth connection: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS error opening {port}: {e}", file=sys.stderr)
        return None

def send_data(conn, data):
    try:
        payload = (TRANSMIT_PREFIX + data).encode("utf-8")
        bytes_written = conn.write(payload)
        conn.flush()
        print(f"Sent ({bytes_written} bytes): {payload!r}")
        return True
    except serial.SerialException as e:
        print(f"Error sending data: {e}", file=sys.stderr)
        return False
    except OSError as e:
        print(f"OS error during write: {e}", file=sys.stderr)
        return False

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    conn = open_bluetooth_connection(BLUETOOTH_PORT, BAUD_RATE)
    if conn is None:
        sys.exit(1)

    try:
        while _running:
            try:
                user_input = input("Enter data to send (or 'q' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input.lower() == "q":
                print("Quit requested by user.")
                break

            if not send_data(conn, user_input):
                print("Transmission failed; continuing.", file=sys.stderr)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if conn and conn.is_open:
            try:
                conn.close()
                print("Bluetooth connection closed.")
            except Exception as e:
                print(f"Error closing connection: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()

