import logging
import signal
import sys
import threading
import time
from pathlib import Path

import cv2
import face_recognition
from picamera2 import Picamera2
from gpiozero import OutputDevice

ENCODINGS_FILE = "encodings.json"
DEFAULT_MOTION_THRESHOLD = 500
DEFAULT_CONFIDENCE_THRESHOLD = 0.6
DEFAULT_DOOR_OPEN_DURATION = 5
DEFAULT_DEBOUNCE_TIME = 2
DEFAULT_LOG_LEVEL = "INFO"

running = True
relay_lock = threading.Lock()


def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down...")
    running = False


def load_encodings(path: str) -> dict:
    try:
        return json.loads(Path(path).read_text())
    except FileNotFoundError:
        logging.warning(f"Encodings file '{path}' not found; starting with empty set.")
        return {}
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in '{path}': {e}; using empty set.")
        return {}


def save_encodings(path: str, encodings: dict) -> None:
    try:
        Path(path).write_text(json.dumps(encodings, indent=2))
    except OSError as e:
        logging.error(f"Failed to save encodings to '{path}': {e}")


def detect_motion(frame1: "numpy.ndarray", frame2: "numpy.ndarray", threshold: int) -> bool:
    diff = cv2.absdiff(frame1, frame2)
    total_diff = int(diff.sum() / diff.size)
    return total_diff > threshold


def recognize_face(frame: "numpy.ndarray", known_encodings: dict) -> tuple[str, float]:
    rgb_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
    face_locations = face_recognition.face_locations(rgb_frame)
    if not face_locations:
        return "Unknown", 0.0
    face_encodings = face_recognition.face_encodings(rgb_frame, face_locations)
    if not face_encodings:
        return "Unknown", 0.0
    best_name = "Unknown"
    best_confidence = 0.0
    for face_encoding in face_encodings:
        matches = face_recognition.compare_faces(list(known_encodings.values()), face_encoding)
        distances = face_recognition.face_distance(list(known_encodings.values()), face_encoding)
        if not matches or distances.size == 0:
            continue
        best_idx = int(distances.argmin())
        if matches[best_idx]:
            name = list(known_encodings.keys())[best_idx]
            confidence = 1.0 - float(distances[best_idx])
            if confidence > best_confidence:
                best_name = name
                best_confidence = confidence
    return best_name, best_confidence


def activate_relay(relay: OutputDevice, duration: float, debounce_time: float) -> None:
    with relay_lock:
        if relay.is_active:
            logging.info("Relay already active; skipping trigger.")
            return
        logging.info(f"Activating relay for {duration}s (debounce {debounce_time}s).")
        relay.on()
        time.sleep(duration)
        relay.off()
        logging.info("Relay deactivated.")


def main() -> None:
    global running

    parser = argparse.ArgumentParser(description="Raspberry Pi facial recognition door access system.")
    parser.add_argument("--motion_threshold", type=int, default=DEFAULT_MOTION_THRESHOLD,
                        help="Pixel difference threshold for motion detection (default: %(default)s).")
    parser.add_argument("--confidence_threshold", type=float, default=DEFAULT_CONFIDENCE_THRESHOLD,
                        help="Face recognition confidence threshold (default: %(default)s).")
    parser.add_argument("--door_open_duration", type=float, default=DEFAULT_DOOR_OPEN_DURATION,
                        help="Relay activation duration in seconds (default: %(default)s).")
    parser.add_argument("--debounce_time", type=float, default=DEFAULT_DEBOUNCE_TIME,
                        help="Debounce time in seconds (default: %(default)s).")
    parser.add_argument("--log_level", type=str, default=DEFAULT_LOG_LEVEL,
                        choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"],
                        help="Logging level (default: %(default)s).")
    args = parser.parse_args()

    logging.basicConfig(
        level=getattr(logging, args.log_level.upper(), logging.INFO),
        format="%(asctime)s - %(levelname)s - %(message)s",
    )

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    picam2 = None
    relay = None
    try:
        picam2 = Picamera2()
        picam2.configure(
            picam2.create_preview_configuration(
                main={"format": "XRGB8888", "size": (640, 480)}
            )
        )
        picam2.start()
        logging.info("Camera initialized at 640x480 XRGB8888.")
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}")
        sys.exit(1)

    try:
        relay = OutputDevice(17, active_high=True, initial_value=False)
        logging.info("Relay initialized on GPIO 17.")
    except Exception as e:
        logging.error(f"Failed to initialize relay on GPIO 17: {e}")
        if picam2:
            picam2.stop()
        sys.exit(1)

    known_encodings = load_encodings(ENCODINGS_FILE)
    logging.info(f"Loaded {len(known_encodings)} known encoding(s).")

    try:
        while running:
            try:
                frame = picam2.capture_array()
            except Exception as e:
                logging.error(f"Frame capture error: {e}")
                time.sleep(0.1)
                continue

            if frame is None:
                logging.warning("Captured empty frame; skipping.")
                continue

            try:
                gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            except cv2.error as e:
                logging.error(f"Gray conversion failed: {e}")
                continue

            try:
                previous_frame = current_frame
                current_frame = gray
            except NameError:
                previous_frame = current_frame = gray
                continue

            if detect_motion(previous_frame, current_frame, args.motion_threshold):
                name, confidence = recognize_face(frame, known_encodings)
                if confidence > args.confidence_threshold:
                    logging.info(f"Access granted for {name} (confidence: {confidence:.2f}).")
                    activate_relay(relay, args.door_open_duration, args.debounce_time)
                else:
                    logging.info(f"Access denied for {name} (confidence: {confidence:.2f}).")
            else:
                logging.debug("No significant motion detected.")
    finally:
        logging.info("Cleaning up resources...")
        if picam2:
            try:
                picam2.stop()
            except Exception as e:
                logging.error(f"Error stopping camera: {e}")
        if relay:
            try:
                relay.close()
            except Exception as e:
                logging.error(f"Error closing relay: {e}")
        logging.info("Shutdown complete.")


if __name__ == "__main__":
    main()

