import io
import logging
import signal
import threading
import time
from typing import Callable, Optional

import cv2
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import Output

logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class WebSocketHandler:
    """Minimal WebSocket handler tracking active connections and broadcasting data."""

    def __init__(self):
        self._lock = threading.Lock()
        self._connections: set = set()

    def has_connections(self) -> bool:
        with self._lock:
            return bool(self._connections)

    def add_connection(self, _):
        with self._lock:
            self._connections.add(_)

    def remove_connection(self, _):
        with self._lock:
            self._connections.discard(_)

    def broadcast(self, data: bytes) -> None:
        with self._lock:
            if not self._connections:
                return
            for conn in list(self._connections):
                try:
                    conn.send(data)
                except Exception as exc:
                    logger.warning(f"Broadcast send error: {exc}")
                    self._connections.discard(conn)


class CameraHandler:
    """Manages the Raspberry Pi camera, motion detection, and WebSocket streaming."""

    def __init__(self, detect_motion_function: Callable[[np.ndarray, np.ndarray], None],
                 websocket_handler: WebSocketHandler):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        if not isinstance(websocket_handler, WebSocketHandler):
            raise TypeError("websocket_handler must be a WebSocketHandler instance")

        self.detect_motion_function = detect_motion_function
        self.websocket_handler = websocket_handler
        self.camera: Optional[Picamera2] = None
        self._stop_event = threading.Event()
        self._lock = threading.Lock()
        self._prev_frame: Optional[np.ndarray] = None
        self._current_frame: Optional[np.ndarray] = None
        self._loop: Optional[threading.Thread] = None

    def _process_jpeg_frame(self, data: bytes) -> None:
        """Decode JPEG bytes and run motion detection on consecutive frames."""
        try:
            if data.startswith(b'\xff\xd8'):
                frame = cv2.imdecode(np.frombuffer(data, np.uint8), cv2.IMREAD_COLOR)
                if frame is None:
                    logger.warning("Failed to decode JPEG frame")
                    return
                if self._prev_frame is not None:
                    try:
                        self.detect_motion_function(self._prev_frame, frame)
                    except Exception as exc:
                        logger.error(f"Motion detection error: {exc}")
                self._prev_frame = self._current_frame
                self._current_frame = frame
        except Exception as exc:
            logger.error(f"Frame processing error: {exc}")

    def _broadcast(self, data: bytes) -> None:
        """Thread-safe broadcast of JPEG data to connected WebSocket clients."""
        try:
            self.websocket_handler.broadcast(data)
        except Exception as exc:
            logger.error(f"Broadcast error: {exc}")

    def _camera_loop(self) -> None:
        """Background loop: decode JPEG from the MJPEG encoder and broadcast."""
        try:
            self.camera.start()
            logger.info("Camera started")
        except Exception as exc:
            logger.error(f"Camera start error: {exc}")
            return

        try:
            while not self._stop_event.is_set():
                try:
                    frame = self.camera.capture_array()
                except Exception as exc:
                    logger.error(f"Capture error: {exc}")
                    time.sleep(0.1)
                    continue

                if frame is None:
                    continue

                ok, encoded = cv2.imencode('.jpg', frame)
                if not ok:
                    logger.warning("JPEG encode failed")
                    continue

                jpeg_bytes = encoded.tobytes()
                self._process_jpeg_frame(jpeg_bytes)

                if self.websocket_handler.has_connections():
                    self._broadcast(jpeg_bytes)
        finally:
            try:
                self.camera.stop()
            except Exception:
                pass
            logger.info("Camera loop stopped")

    def start(self) -> None:
        """Initialize the camera, start the background loop, and install signal handlers."""
        try:
            self.camera = Picamera2()
            config = self.camera.create_video_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                lores={"size": (640, 480), "format": "YUV420"},
                encode="lores"
            )
            self.camera.configure(config)
            self.camera.start()
            logger.info("Camera initialized: 640x480 @ 10 fps")
        except Exception as exc:
            logger.error(f"Camera initialization error: {exc}")
            self.camera = None
            return

        self._stop_event.clear()
        self._loop = threading.Thread(target=self._camera_loop, daemon=True)
        self._loop.start()

        def _signal_handler(signum, _frame):
            logger.info(f"Signal {signum} received, shutting down")
            self.stop()

        signal.signal(signal.SIGINT, _signal_handler)
        signal.signal(signal.SIGTERM, _signal_handler)

    def stop(self) -> None:
        """Stop the camera and join the background thread."""
        if self._stop_event.is_set():
            return
        self._stop_event.set()
        if self._loop and self._loop.is_alive():
            self._loop.join(timeout=5)
        with self._lock:
            if self.camera:
                try:
                    self.camera.stop()
                except Exception:
                    pass
                self.camera = None
        logger.info("Camera stopped and resources released")

    def get_latest_frame(self) -> Optional[np.ndarray]:
        with self._lock:
            return self._current_frame

