import io
import logging
import numpy as np
import cv2
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Buffer for picamera2 MJPEG stream with selective frame flushing.

    Only non-I-frame H.264 frames are flushed to the output sink.
    """

    def __init__(self, c):
        if not isinstance(c, Picamera2):
            raise TypeError("c must be a picamera2.Picamera2 instance")
        self.c = c
        self.b = io.BytesIO()
        self._frame_started = False
        self._frame_type = None

    def write(self, d):
        """Accumulate bytes; flush non-I-frame complete frames to sink."""
        try:
            self.b.write(d)
            # Detect frame completion via picamera2 metadata
            metadata = self.c.current_configuration()['encode']
            if metadata and metadata.get('frame_complete'):
                self._frame_type = metadata.get('frame_type', 0)
                self._frame_started = True
            else:
                # Fallback heuristic: if we see a NAL unit start code, treat as frame end
                if d.startswith(b'\x00\x00\x01'):
                    self._frame_type = 0  # placeholder; real detection would parse NAL
                    self._frame_started = True

            if self._frame_started:
                if self._frame_type != 1:  # not I-frame
                    self._flush()
                self._frame_started = False
                self._frame_type = None
        except Exception as e:
            logger.error(f"Error in CameraStreamBuffer.write: {e}")

    def _flush(self):
        """Flush accumulated buffer to output sink."""
        try:
            data = self.b.getvalue()
            if data:
                # In picamera2, the output is configured via the encoder's output callback
                # Here we assume a sink object with a write method
                # For a real implementation, you would pass a sink object during init
                logger.debug(f"Flushed {len(data)} bytes to sink")
            self.b.seek(0)
            self.b.truncate()
        except Exception as e:
            logger.error(f"Error flushing buffer: {e}")

    def close(self):
        self.b.close()


class MotionDetectionBuffer:
    """Buffer for picamera2 MJPEG stream with motion detection via callback."""

    def __init__(self, f):
        if not callable(f):
            raise TypeError("f must be a callable accepting (prev_frame, curr_frame)")
        self.f = f
        self.b = io.BytesIO()
        self.prev_frame = None
        self._frame_started = False

    def write(self, d):
        """Parse MJPEG stream; decode SOI marker to trigger motion detection."""
        try:
            if d.startswith(b'\xff\xd8'):  # SOI marker
                if self.b.tell() > 0:
                    # Previous frame complete
                    data = self.b.getvalue()
                    if data:
                        try:
                            self.prev_frame = cv2.imdecode(
                                np.frombuffer(data, dtype=np.uint8),
                                cv2.IMREAD_COLOR
                            )
                        except Exception as e:
                            logger.error(f"Error decoding previous frame: {e}")
                            self.prev_frame = None
                    self.b.seek(0)
                    self.b.truncate()

                # Decode current frame
                try:
                    curr_data = d
                    curr_frame = cv2.imdecode(
                        np.frombuffer(curr_data, dtype=np.uint8),
                        cv2.IMREAD_COLOR
                    )
                    if curr_frame is not None:
                        if self.prev_frame is not None:
                            self.f(self.prev_frame, curr_frame)
                        self.prev_frame = curr_frame
                except Exception as e:
                    logger.error(f"Error decoding current frame: {e}")
            else:
                self.b.write(d)
        except Exception as e:
            logger.error(f"Error in MotionDetectionBuffer.write: {e}")

    def close(self):
        self.b.close()

