from smbus2 import SMBus
from luma.core.interface.serial import i2c as luma_i2c
from luma.oled.device import ssd1306

I2C_BUS = 1
LIGHT_SENSOR_ADDR = 0x23
OLED_ADDR = 0x3C

# BH1750 One-Time High-Resolution Mode command
LIGHT_CMD = 0x20
CONVERSION_DELAY_S = 0.120
UPDATE_INTERVAL_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_light_lux(bus: SMBus) -> float | None:
    """Trigger a one-shot high-res measurement and return lux, or None on error."""
    try:
        bus.write_byte(LIGHT_SENSOR_ADDR, LIGHT_CMD)
    except OSError:
        return None

    time.sleep(CONVERSION_DELAY_S)

    try:
        data = bus.read_i2c_block_data(LIGHT_SENSOR_ADDR, 0x00, 2)
    except OSError:
        return None

    raw = (data[0] << 8) | data[1]
    return raw / 1.2


def lux_to_contrast(lux: float) -> int:
    return int(max(0.0, min(255.0, lux)))


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        return 1

    try:
        serial = luma_i2c(port=I2C_BUS, address=OLED_ADDR)
        device = ssd1306(serial)
    except OSError as exc:
        print(f"Error: cannot initialize SSD1306 at 0x{OLED_ADDR:02X}: {exc}", file=sys.stderr)
        bus.close()
        return 1

    current_contrast = device.contrast()
    print(f"Initial contrast: {current_contrast}")

    try:
        while _running:
            lux = read_light_lux(bus)
            if lux is None:
                print("Warning: light sensor read failed; keeping previous contrast.", file=sys.stderr)
            else:
                current_contrast = lux_to_contrast(lux)
                try:
                    device.contrast(current_contrast)
                except OSError as exc:
                    print(f"Warning: failed to set contrast: {exc}", file=sys.stderr)

            time.sleep(UPDATE_INTERVAL_S)
    finally:
        try:
            device.clear()
        except OSError:
            pass
        bus.close()

    return 0


if __name__ == "__main__":
    sys.exit(main())

