import time
import signal
import sys
import board
import busio
import adafruit_character_lcd.character_lcd_i2c as character_lcd
import adafruit_dht

# --- Configuration -----------------------------------------------------------
I2C_ADDR = 0x27
DHT_PIN = board.D4
LCD_COLS = 16
LCD_ROWS = 2
UPDATE_INTERVAL_S = 2.0

# --- Globals for cleanup -----------------------------------------------------
lcd = None
dht = None
running = True


def cleanup():
    """Clear the LCD on any exit path."""
    global lcd
    if lcd is not None:
        try:
            lcd.clear()
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global running
    running = False


def init_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize I2C bus: {exc}", file=sys.stderr)
        return None


def init_lcd(i2c_bus):
    """Initialize the 16x2 I2C character LCD at the given address."""
    try:
        return character_lcd.Character_LCD_I2C(i2c_bus, LCD_COLS, LCD_ROWS, address=I2C_ADDR)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize LCD at 0x{I2C_ADDR:02X}: {exc}", file=sys.stderr)
        return None


def init_dht():
    """Initialize the DHT22 sensor on the given pin."""
    try:
        return adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize DHT22 on {DHT_PIN}: {exc}", file=sys.stderr)
        return None


def read_dht22(sensor):
    """Read temperature (C) and humidity (%) from the DHT22.

    Returns (temperature, humidity) or (None, None) on error.
    """
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except RuntimeError as exc:
        # DHT22 checksum errors or timing glitches are common; log and retry.
        print(f"[WARN] DHT22 read error (checksum/timing): {exc}", file=sys.stderr)
        return None, None
    except Exception as exc:
        print(f"[ERROR] Unexpected DHT22 read error: {exc}", file=sys.stderr)
        return None, None


def main():
    global lcd, dht

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = init_i2c()
    if i2c_bus is None:
        sys.exit(1)

    lcd = init_lcd(i2c_bus)
    if lcd is None:
        sys.exit(1)

    dht = init_dht()
    if dht is None:
        sys.exit(1)

    try:
        while running:
            temperature, humidity = read_dht22(dht)

            if temperature is not None and humidity is not None:
                lcd.message = f"Temp: {temperature:.1f} C\nHumidity: {humidity:.1f}%"
            else:
                lcd.message = "Sensor Error\nCheck wiring"

            time.sleep(UPDATE_INTERVAL_S)

    except Exception as exc:
        print(f"[ERROR] Unexpected runtime error: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

