        try:
            self.serial = i2c(port=self.i2c_port, address=self.i2c_address)
            self.device = ssd1306(self.serial)
            logging.info("OLED display initialized successfully.")
        except DeviceNotFoundError:
            logging.error(f"OLED display not found at I2C address 0x{self.i2c_address:02X} on bus {self.i2c_port}.")
            return False
        except Exception as e:
            logging.error(f"Error initializing OLED display: {e}")
            return False
        return True

    def load_gifs(self, folder_path):
        if not os.path.isdir(folder_path):
            logging.error(f"Invalid folder path: {folder_path}")
            return False
        try:
            self.gif_files = [f for f in os.listdir(folder_path) if f.lower().endswith('.gif')]
            if not self.gif_files:
                logging.warning(f"No GIF files found in {folder_path}")
                return False
            logging.info(f"Found {len(self.gif_files)} GIF file(s) in {folder_path}")
            return True
        except Exception as e:
            logging.error(f"Error loading GIF files: {e}")
            return False

    def play_gif(self, gif_filename, loop_count=0):
        if not self.device:
            logging.error("Display not initialized. Call initialize() first.")
            return
        if not gif_filename:
            logging.error("No GIF file specified.")
            return
        if not os.path.exists(gif_filename):
            logging.error(f"GIF file not found: {gif_filename}")
            return
        if not self.gif_files or gif_filename not in self.gif_files:
            logging.error(f"GIF file {gif_filename} not loaded. Call load_gifs() first.")
            return
        try:
            with Image.open(gif_filename) as image:
                self.current_gif = image
                self.current_frame = 0
                self.loop_count = loop_count
                self.frame_interval = image.info.get('duration', 100) / 1000.0
                self.running = True
                self._play_loop()
        except Exception as e:
            logging.error(f"Error playing GIF: {e}")

    def _play_loop(self):
        if not self.running:
