        try:
            loop_count = self.loop_count
            while self.running:
                frame = self.current_gif.convert('RGB').resize((self.frame_width, self.frame_height))
                frame = ImageOps.pad(frame, (self.frame_width, self.frame_height), method=Image.NEAREST, color=(0, 0, 0))
                frame = frame.convert('1')
                with canvas(self.device) as draw:
                    draw.image(frame)
                time.sleep(self.frame_interval)
                self.current_frame = (self.current_frame + 1) % self.current_gif.n_frames
                if self.current_frame == 0:
                    if loop_count == 0:
                        continue
                    loop_count -= 1
                    if loop_count == 0:
                        break
        except Exception as e:
            logging.error(f"Error during GIF playback: {e}")
        finally:
            self.current_gif = None
            self.running = False
            logging.info("GIF playback stopped.")

    def stop(self):
        self.running = False
        if self.device:
            try:
                self.device.cleanup()
            except Exception:
                pass
        if self.serial:
            try:
                self.serial.cleanup()
            except Exception:
                pass
        logging.info("Display stopped and resources released.")

def main():
    display = GIFDisplay()
    if not display.initialize():
        return
    signal.signal(signal.SIGINT, lambda s, f: display.stop())
    if not display.load_gifs('/home/pi/gifs'):
        display.stop()
        return
    display.play_gif('/home/pi/gifs/example.gif', loop_count=0)
    try:
        while display.running:
            time.sleep(0.1)
    except KeyboardInterrupt:
        pass
    finally:
        display.stop()

if __name__ == '__main__':
    main()

