import time
import sys
import board
import adafruit_dht

# DHT11 data pin connected to GPIO4 (BCM) / physical pin 7
DATA_PIN = board.D4

# Retry configuration
MAX_RETRIES = 5
RETRY_DELAY = 2  # seconds; DHT11 requires >= 1 s between reads


def read_dht11(sensor):
    """Attempt to read temperature/humidity from the DHT11 sensor.

    Returns (temperature_c, humidity) on success, or (None, None) on failure.
    """
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temperature_c = sensor.temperature
            humidity = sensor.humidity
            if temperature_c is not None and humidity is not None:
                return temperature_c, humidity
        except RuntimeError as exc:
            # Common DHT11 errors: checksum failure, timeout, or missing data
            print(f"Attempt {attempt}/{MAX_RETRIES} failed: {exc}")
        except Exception as exc:
            # Unexpected error (e.g., sensor disconnected, I/O error)
            print(f"Attempt {attempt}/{MAX_RETRIES} failed: {exc}")

        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY)

    return None, None


def main():
    sensor = None
    try:
        # Initialize the DHT11 sensor on GPIO4
        sensor = adafruit_dht.DHT11(DATA_PIN, use_pulseio=False)

        temperature_c, humidity = read_dht11(sensor)

        if temperature_c is not None and humidity is not None:
            print(f"Temperature: {temperature_c:.1f}°C")
            sys.exit(0)
        else:
            print("Failed to retrieve data from DHT11 after all retries.")
            sys.exit(1)

    except KeyboardInterrupt:
        print("\nScript interrupted by user.")
        sys.exit(130)
    except Exception as exc:
        print(f"Fatal error: {exc}")
        sys.exit(1)
    finally:
        # Release the sensor resource on every exit path
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass


if __name__ == "__main__":
    main()

