#!/usr/bin/env python3
"""
Clean Energy Monitoring System Simulator for Raspberry Pi 4

Simulates light, temperature, voltage, and current sensors on GPIO17 and GPIO4.
Reads the Raspberry Pi's internal temperature via vcgencmd.
Logs data every 5 seconds with threshold-triggered warnings.
Uses gpiozero for GPIO access and subprocess for vcgencmd.
"""

import time
import datetime
import random
import subprocess
import sys
import signal
from gpiozero import InputDevice

# GPIO pin definitions (BCM numbering)
LIGHT_SENSOR_PIN = 17
TEMP_SENSOR_PIN = 4

# Thresholds
LIGHT_THRESHOLD = 300
TEMP_THRESHOLD = 35.0
PI_TEMP_THRESHOLD = 75.0

# Global device references for cleanup
_devices = []


def setup_gpio():
    """Initialize GPIO17 and GPIO4 as simulated input devices using gpiozero."""
    global _devices
    try:
        light = InputDevice(LIGHT_SENSOR_PIN, pull_up=False)
        temp = InputDevice(TEMP_SENSOR_PIN, pull_up=False)
        _devices = [light, temp]
        print(f"GPIO setup successful: GPIO{LIGHT_SENSOR_PIN} and GPIO{TEMP_SENSOR_PIN} initialized as input.")
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        sys.exit(1)


def get_simulated_light_level():
    """Simulate light level (lux) based on current time."""
    now = datetime.datetime.now()
    hour = now.hour
    if 6 <= hour < 18:
        return random.randint(600, 1000)
    else:
        return random.randint(100, 300)


def get_simulated_temperature():
    """Simulate temperature (°C)."""
    return random.uniform(20, 30)


def get_simulated_voltage():
    """Simulate battery voltage (V)."""
    if get_simulated_light_level() > 300:
        return random.uniform(11.5, 12.5)
    else:
        return random.uniform(10.0, 11.0)


def get_simulated_current():
    """Simulate battery current (A)."""
    if get_simulated_light_level() > 300:
        return random.uniform(1.5, 2.5)
    else:
        return random.uniform(0.5, 1.0)


def get_pi_temperature():
    """Read Raspberry Pi internal temperature via vcgencmd.

    Returns:
        float: Temperature in °C, or None on error.
    """
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True,
            text=True,
            timeout=5,
            check=True
        )
        # Output format: temp=XX.X'C
        temp_str = result.stdout.strip()
        return float(temp_str.split('=')[1].split("'")[0])
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired,
            IndexError, ValueError, FileNotFoundError) as e:
        print(f"Error reading Pi temperature: {e}")
        return None


def log_data(light, temperature, voltage, current, pi_temp):
    """Log sensor data and trigger threshold warnings."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"{timestamp} - Light: {light} lux, Temperature: {temperature:.2f}°C, "
          f"Voltage: {voltage:.2f}V, Current: {current:.2f}A, Pi Temp: {pi_temp if pi_temp is not None else 'N/A'}°C")

    if light < LIGHT_THRESHOLD:
        print(f"{timestamp} - WARNING: Possible solar panel performance issue detected (light level: {light} lux).")
    if temperature > TEMP_THRESHOLD:
        print(f"{timestamp} - WARNING: Simulated cooling system activated (temperature: {temperature:.2f}°C).")
    if pi_temp is not None and pi_temp > PI_TEMP_THRESHOLD:
        print(f"{timestamp} - CRITICAL: Simulated system shutdown due to high Pi temperature (temperature: {pi_temp:.2f}°C).")


def cleanup():
    """Close all gpiozero device objects."""
    for dev in _devices:
        try:
            dev.close()
        except Exception:
            pass
    _devices.clear()


def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for graceful shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    cleanup()
    sys.exit(0)


def main():
    """Main loop: simulate sensors, read Pi temperature, log data, handle thresholds."""
    setup_gpio()

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

    try:
        while True:
            light = get_simulated_light_level()
            temperature = get_simulated_temperature()
            voltage = get_simulated_voltage()
            current = get_simulated_current()
            pi_temp = get_pi_temperature()

            log_data(light, temperature, voltage, current, pi_temp)
            time.sleep(5)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()
        print("GPIO cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

