    if temperature > TEMP_THRESHOLD:
        print(f"{timestamp} - WARNING: Simulated cooling system activated (temperature: {temperature:.2f}°C).")
    if pi_temp is not None and pi_temp > PI_TEMP_THRESHOLD:
        print(f"{timestamp} - CRITICAL: Simulated system shutdown due to high Pi temperature (temperature: {pi_temp:.2f}°C).")


def cleanup():
    """Close all gpiozero device objects."""
    for dev in _devices:
        try:
            dev.close()
        except Exception:
            pass
    _devices.clear()


def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for graceful shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    cleanup()
    sys.exit(0)


def main():
    """Main loop: simulate sensors, read Pi temperature, log data, handle thresholds."""
    setup_gpio()

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

