                self.bus.write_i2c_block_data(self.DHT20_I2C_ADDR, self.DHT20_MEASURE_REG, self.MEASURE_CMD)
                timeout = 0.1
                start = time.time()
                while True:
                    status = self.bus.read_byte_data(self.DHT20_I2C_ADDR, self.DHT20_STATUS_REG)
                    if (status & 0x80) == 0:
