def initialize_i2c():
    """Initializes the I2C bus on board.SCL (GPIO3) and board.SDA (GPIO2)."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        # Verify the bus is responsive by scanning for any device
        while not i2c_bus.try_lock():
            pass
        devices = i2c_bus.scan()
        i2c_bus.unlock()
        if not devices:
            print("Warning: No I2C devices detected on the bus.")
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_multiplexer(i2c_bus, address=I2C_ADDRESS_TCA9548A):
    """Initializes the TCA9548A I2C multiplexer."""
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus, address=address)
        return multiplexer
    except ValueError as e:
        print(f"Error: TCA9548A multiplexer not found at address 0x{address:02X}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None


def initialize_bme280(multiplexer, channel=BME280_I2C_CHANNEL):
    """Initializes the BME280 sensor on the specified multiplexer channel."""
    try:
        sensor = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[channel])
        return sensor
    except ValueError as e:
        print(f"Error: BME280 sensor not found on channel {channel}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")
        return None


def initialize_tsl2591(multiplexer, channel=TSL2591_I2C_CHANNEL):
    """Initializes the TSL2591 sensor on the specified multiplexer channel."""
    try:
        sensor = adafruit_tsl2591.TSL2591(multiplexer[channel])
        return sensor
    except ValueError as e:
        print(f"Error: TSL2591 sensor not found on channel {channel}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing TSL2591 sensor: {e}")
        return None


def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Reads temperature, humidity, and light intensity from the sensors."""
    try:
        temperature = bme280_sensor.temperature
        humidity = bme280_sensor.humidity
        light_intensity = tsl2591_sensor.lux
        return temperature, humidity, light_intensity
    except OSError as e:
        print(f"I2C bus error reading sensor data: {e}")
        return None, None, None
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None


def display_sensor_data(temperature, humidity, light_intensity):
    """Prints the sensor data to the console."""
    if temperature is not None and humidity is not None and light_intensity is not None:
        print(f"Temperature: {temperature:.2f} C")
        print(f"Humidity: {humidity:.2f} %")
        print(f"Light Intensity: {light_intensity:.2f} lux")
        print()


def main():
    """Main function to initialize and run the sensor readings."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280_sensor = initialize_bme280(multiplexer)
    tsl2591_sensor = initialize_tsl2591(multiplexer)

    if bme280_sensor is None or tsl2591_sensor is None:
        print("Warning: One or more sensors failed to initialize. Continuing with available sensors.")

    try:
        while True:
            temperature, humidity, light_intensity = read_sensor_data(bme280_sensor, tsl2591_sensor)
            display_sensor_data(temperature, humidity, light_intensity)
            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Exiting program.")


if __name__ == "__main__":
    main()

