import RPi.GPIO as GPIO
import time
import sys

DHT_PIN = 4
MAX_RETRIES = 3
RETRY_DELAY = 2.0
ERROR_DELAY = 5.0
LOOP_INTERVAL = 5.0
START_SIGNAL_LOW_US = 18000
RESPONSE_LOW_US = 80
RESPONSE_HIGH_US = 80
BIT_SAMPLE_US = 50
READ_TIMEOUT_S = 0.1

def read_dht22():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(DHT_PIN, GPIO.OUT)
    GPIO.output(DHT_PIN, GPIO.HIGH)
    time.sleep(0.1)

    for attempt in range(1, MAX_RETRIES + 1):
        try:
            GPIO.setup(DHT_PIN, GPIO.OUT)
            GPIO.output(DHT_PIN, GPIO.LOW)
            time.sleep(0.000018)
            GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

            timeout = time.time() + READ_TIMEOUT_S
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                if time.time() > timeout:
                    raise TimeoutError("Sensor not responding (stuck high)")
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                if time.time() > timeout:
                    raise TimeoutError("Sensor not responding (stuck low)")
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                if time.time() > timeout:
                    raise TimeoutError("Sensor response too long")

            data = []
            for _ in range(40):
                while GPIO.input(DHT_PIN) == GPIO.LOW:
                    if time.time() > timeout:
                        raise TimeoutError("Bit start timeout")
                start = time.time()
                while GPIO.input(DHT_PIN) == GPIO.HIGH:
                    if time.time() > timeout:
                        raise TimeoutError("Bit end timeout")
                duration = time.time() - start
                data.append(1 if duration > BIT_SAMPLE_US / 2 else 0)

            if len(data) != 40:
                raise ValueError(f"Expected 40 bits, got {len(data)}")

            humidity_int = int(''.join(map(str, data[0:8])), 2)
            humidity_dec = int(''.join(map(str, data[8:16])), 2)
            temp_int = int(''.join(map(str, data[16:24])), 2)
            temp_dec = int(''.join(map(str, data[24:32])), 2)
            checksum = int(''.join(map(str, data[32:40])), 2)

            calculated = (humidity_int + humidity_dec + temp_int + temp_dec) & 0xFF
            if calculated != checksum:
                raise ValueError(f"Checksum mismatch: calculated {calculated}, received {checksum}")

            humidity = humidity_int + humidity_dec / 10.0
            temperature = temp_int + temp_dec / 10.0
            if temp_int >= 128:
                temperature -= 512.0
            if humidity_int >= 128:
                humidity -= 512.0

            print(f"Temperature: {temperature:.1f}°C")
            print(f"Humidity: {humidity:.1f}%")
            return

        except (TimeoutError, ValueError, RuntimeError) as e:
            print(f"Attempt {attempt}/{MAX_RETRIES} failed: {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
            else:
                print("Max retries reached. Waiting 5 seconds before next attempt.")
                time.sleep(ERROR_DELAY)

    print("Sensor read failed after all retries.")

def cleanup():
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    try:
        while True:
            read_dht22()
            time.sleep(LOOP_INTERVAL)
    except KeyboardInterrupt:
        print("\nExiting...")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

