import config
import signal
import sys
import time
import logging
import threading

import paho.mqtt.client as mqtt
import adafruit_dht
import board

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("dht22_homie")

DEGREE_CELSIUS = "\u00B0C"

running = True
mqtt_client = None
dht_sensor = None


def signal_handler(signum, frame):
    global running
    log.info("Signal %s received, shutting down...", signum)
    running = False


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        log.info("Connected to MQTT broker")
    else:
        log.error("MQTT connection failed with reason code %s", reason_code)


def on_disconnect(client, userdata, flags, reason_code, properties):
    log.warning("Disconnected from MQTT broker (reason code %s)", reason_code)


def publish(topic, payload):
    if mqtt_client is None or not mqtt_client.is_connected():
        log.warning("MQTT client not connected; cannot publish %s", topic)
        return
    try:
        full_topic = f"homie/{config.homieclientid}/{topic}"
        info = mqtt_client.publish(full_topic, str(payload), qos=1)
        info.wait_for_publish(timeout=5)
        log.debug("Published %s -> %s", full_topic, payload)
    except Exception as e:
        log.error("Error publishing to %s: %s", topic, e)


def publish_homie_discovery():
    publish("$homie", "4.0")
    publish("$name", config.homieclientname)
    publish("$nodes", config.homienodes)

    publish(f"{config.homienodes}/$name", "DHT22 Sensor")
    publish(f"{config.homienodes}/$properties", "temperature,humidity")

    publish(f"{config.homienodes}/temperature/$name", "Temperature")
    publish(f"{config.homienodes}/temperature/$unit", DEGREE_CELSIUS)
    publish(f"{config.homienodes}/temperature/$datatype", "float")
    publish(f"{config.homienodes}/temperature/$settable", "false")

    publish(f"{config.homienodes}/humidity/$name", "Humidity")
    publish(f"{config.homienodes}/humidity/$unit", "%")
    publish(f"{config.homienodes}/humidity/$datatype", "float")
    publish(f"{config.homienodes}/humidity/$settable", "false")


def read_dht22():
    global dht_sensor
    if dht_sensor is None:
        try:
            dht_sensor = adafruit_dht.DHT22(board.D4, use_pulseio=False)
            log.info("DHT22 initialized on GPIO4")
        except Exception as e:
            log.error("Failed to initialize DHT22: %s", e)
            return None, None

    for attempt in range(3):
        try:
            temperature = dht_sensor.temperature
            humidity = dht_sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            log.warning("DHT22 read attempt %d failed: %s", attempt + 1, e)
        except Exception as e:
            log.error("Unexpected DHT22 error: %s", e)
            break
        time.sleep(2)

    log.error("DHT22 read failed after 3 attempts")
    return None, None


def connect_mqtt():
    global mqtt_client
    try:
        mqtt_client = mqtt.Client(
            callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
        )
        if config.mqttusername and config.mqttpassword:
            mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)
        mqtt_client.on_connect = on_connect
        mqtt_client.on_disconnect = on_disconnect
        mqtt_client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
        mqtt_client.loop_start()
        time.sleep(1)
        if not mqtt_client.is_connected():
            log.error("MQTT connection timed out")
            return False
        publish_homie_discovery()
        return True
    except Exception as e:
        log.error("MQTT connection error: %s", e)
        return False


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not connect_mqtt():
        log.error("Cannot start without MQTT; exiting")
        sys.exit(1)

    time.sleep(2)

    while running:
        temperature, humidity = read_dht22()
        if temperature is not None and humidity is not None:
            log.info("Temperature = %.1f %s", temperature, DEGREE_CELSIUS)
            log.info("Humidity = %.1f %%", humidity)
            publish(f"{config.homienodes}/temperature", f"{temperature:.1f}")
            publish(f"{config.homienodes}/humidity", f"{humidity:.1f}")
        else:
            log.warning("Skipping publish due to sensor read failure")

        if not running:
            break

        if not mqtt_client.is_connected():
            log.warning("MQTT disconnected; attempting reconnect")
            connect_mqtt()

        for _ in range(config.publishtime):
            if not running:
                break
            time.sleep(1)

    cleanup()


def cleanup():
    global mqtt_client, dht_sensor
    log.info("Cleaning up resources...")
    if mqtt_client is not None:
        try:
            mqtt_client.loop_stop()
            mqtt_client.disconnect()
        except Exception:
            pass
    if dht_sensor is not None:
        try:
            dht_sensor.exit()
        except Exception:
            pass
    log.info("Shutdown complete")


if __name__ == "__main__":
    main()

