        else:
            print("Failed to retrieve data from DHT11 sensor")
    except RuntimeError as e:
        # DHT sensors often throw RuntimeErrors on transient read failures
        print(f"RuntimeError reading DHT11: {e}")

def main():
    """Main function to continuously read and print sensor data."""
    try:
        while True:
            read_sensor()
            time.sleep(5)
    except KeyboardInterrupt:
        print("\nExiting program")
    finally:
        # Release the sensor resources cleanly
        try:
            dht_device.exit()
        except Exception:
            pass

if __name__ == "__main__":
    main()

