import RPi.GPIO as GPIO
import time
import signal
import sys

# Pin definitions
X_DIR_PIN = 17
X_STEP_PIN = 18
X_ENC_A_PIN = 22
X_ENC_B_PIN = 23
Y_DIR_PIN = 27
Y_STEP_PIN = 4
Y_ENC_A_PIN = 24
Y_ENC_B_PIN = 25

# Encoder quadrature decoding state
x_encoder_count = 0
y_encoder_count = 0
x_encoder_state = 0
y_encoder_state = 0
running = True

# Limits
X_MIN = 0
X_MAX = 3000
Y_MIN = 0
Y_MAX = 2000

# Proportional gain for step delay adjustment
Kp = 0.1

def signal_handler(sig, frame):
    global running
    print("\nExiting...")
    running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(X_DIR_PIN, GPIO.OUT)
    GPIO.setup(X_STEP_PIN, GPIO.OUT)
    GPIO.setup(X_ENC_A_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(X_ENC_B_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(Y_DIR_PIN, GPIO.OUT)
    GPIO.setup(Y_STEP_PIN, GPIO.OUT)
    GPIO.setup(Y_ENC_A_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(Y_ENC_B_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def encoder_callback(channel):
    global x_encoder_count, y_encoder_count, x_encoder_state, y_encoder_state
    if channel == X_ENC_A_PIN:
        b_state = GPIO.input(X_ENC_B_PIN)
        if GPIO.input(X_ENC_A_PIN) == GPIO.HIGH:
            if b_state == GPIO.HIGH:
                x_encoder_count += 1
            else:
                x_encoder_count -= 1
        else:
            if b_state == GPIO.HIGH:
                x_encoder_count -= 1
            else:
                x_encoder_count += 1
    elif channel == Y_ENC_A_PIN:
        b_state = GPIO.input(Y_ENC_B_PIN)
        if GPIO.input(Y_ENC_A_PIN) == GPIO.HIGH:
            if b_state == GPIO.HIGH:
                y_encoder_count += 1
            else:
                y_encoder_count -= 1
        else:
            if b_state == GPIO.HIGH:
                y_encoder_count -= 1
            else:
                y_encoder_count += 1

def move_stepper(dir_pin, step_pin, steps, direction):
    GPIO.output(dir_pin, direction)
    time.sleep(0.001)
    for _ in range(steps):
        GPIO.output(step_pin, GPIO.HIGH)
        time.sleep(0.001)
        GPIO.output(step_pin, GPIO.LOW)
        time.sleep(0.001)

def simulate_sensor_reading():
    import random
    return random.uniform(18, 25), random.uniform(40, 60), random.uniform(300, 700)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    setup_gpio()
    GPIO.add_event_detect(X_ENC_A_PIN, GPIO.RISING, callback=encoder_callback)
    GPIO.add_event_detect(Y_ENC_A_PIN, GPIO.RISING, callback=encoder_callback)
    print("Stepper motor control ready. Commands: move x y, scan, set_scan, origin, pos, exit")
    while running:
        try:
            command = input("Enter command: ").strip().lower()
            if command.startswith("move"):
                parts = command.split()
                if len(parts) == 3:
                    x_target = int(parts[1])
                    y_target = int(parts[2])
                    if X_MIN <= x_target <= X_MAX and Y_MIN <= y_target <= Y_MAX:
                        x_steps = x_target - x_encoder_count
                        y_steps = y_target - y_encoder_count
                        if x_steps > 0:
                            move_stepper(X_DIR_PIN, X_STEP_PIN, abs(x_steps), GPIO.HIGH)
                        else:
                            move_stepper(X_DIR_PIN, X_STEP_PIN, abs(x_steps), GPIO.LOW)
                        if y_steps > 0:
                            move_stepper(Y_DIR_PIN, Y_STEP_PIN, abs(y_steps), GPIO.HIGH)
                        else:
                            move_stepper(Y_DIR_PIN, Y_STEP_PIN, abs(y_steps), GPIO.LOW)
                    else:
                        print("Error: Target position out of limits.")
                else:
                    print("Usage: move x y")
            elif command == "scan":
                x_start = int(input("Enter X start: "))
                x_end = int(input("Enter X end: "))
                y_start = int(input("Enter Y start: "))
                y_end = int(input("Enter Y end: "))
                scan_speed = int(input("Enter scan speed (steps/s): "))
                if x_start < x_end and y_start < y_end and scan_speed > 0:
                    x_steps_total = x_end - x_start
                    y_steps_total = y_end - y_start
                    x_steps_remaining = x_steps_total
                    y_steps_remaining = y_steps_total
                    while x_steps_remaining > 0 or y_steps_remaining > 0:
                        if x_steps_remaining > 0:
                            move_stepper(X_DIR_PIN, X_STEP_PIN, min(scan_speed, x_steps_remaining), GPIO.HIGH)
                            x_steps_remaining -= scan_speed
                        else:
                            move_stepper(X_DIR_PIN, X_STEP_PIN, 0, GPIO.LOW)
                        if y_steps_remaining > 0:
                            move_stepper(Y_DIR_PIN, Y_STEP_PIN, min(scan_speed, y_steps_remaining), GPIO.HIGH)
                            y_steps_remaining -= scan_speed
                        else:
                            move_stepper(Y_DIR_PIN, Y_STEP_PIN, 0, GPIO.LOW)
                        temp, hum, air = simulate_sensor_reading()
                        print(f"Temp: {temp:.2f}C, Hum: {hum:.2f}%, Air: {air:.2f}ppm")
                        time.sleep(1)
                else:
                    print("Invalid scan parameters.")
            elif command == "set_scan":
                print("Set scan parameters manually in the scan command.")
            elif command == "origin":
                x_encoder_count = 0
                y_encoder_count = 0
                print("Position reset to origin.")
            elif command == "pos":
                print(f"Current position: X={x_encoder_count}, Y={y_encoder_count}")
            elif command == "exit":
                running = False
            else:
                print("Invalid command.")
        except ValueError:
            print("Invalid input. Please enter numbers.")
        except Exception as e:
            print(f"An error occurred: {e}")
    GPIO.cleanup()
    print("GPIO cleaned up.")

if __name__ == "__main__":
    main()

