import time
import logging
import board
import adafruit_dht

# Configure logging
logging.basicConfig(
    filename='wildlife_monitoring.log',
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# DHT22 sensor pins (BCM numbering)
SENSOR_PINS = [board.D4, board.D17]

# Anomaly thresholds
TEMPERATURE_THRESHOLD = 35.0
HUMIDITY_THRESHOLD = 90.0

# Retry settings
MAX_RETRIES = 3
RETRY_DELAY = 2  # seconds

def read_dht22(pin):
    """Read temperature and humidity from a DHT22 sensor with retry logic.

    Args:
        pin: The board pin object (e.g., board.D4).

    Returns:
        tuple: (temperature_celsius, humidity) as floats, or (None, None) on failure.
    """
    dht_device = None
    try:
        dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
        for attempt in range(1, MAX_RETRIES + 1):
            try:
                temperature = dht_device.temperature
                humidity = dht_device.humidity
                if temperature is not None and humidity is not None:
                    return temperature, humidity
                else:
                    logging.error(
                        f"DHT22 on pin {pin} returned None (attempt {attempt}/{MAX_RETRIES})"
                    )
            except RuntimeError as e:
                logging.error(
                    f"DHT22 on pin {pin} read error (attempt {attempt}/{MAX_RETRIES}): {e}"
                )
            except Exception as e:
                logging.error(
                    f"Unexpected error reading DHT22 on pin {pin} (attempt {attempt}/{MAX_RETRIES}): {e}"
                )
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
        logging.error(f"DHT22 on pin {pin} failed after {MAX_RETRIES} attempts.")
        return None, None
    finally:
        if dht_device is not None:
            try:
                dht_device.exit()
            except Exception:
                pass

def check_anomalies(temperature, humidity, pin):
    """Check for temperature and humidity anomalies and log them."""
    if temperature is not None and temperature > TEMPERATURE_THRESHOLD:
        logging.error(
            f"Temperature anomaly: {temperature:.1f}°C (threshold: {TEMPERATURE_THRESHOLD}°C) on pin {pin}"
        )
    if humidity is not None and humidity > HUMIDITY_THRESHOLD:
        logging.error(
            f"Humidity anomaly: {humidity:.1f}% (threshold: {HUMIDITY_THRESHOLD}%) on pin {pin}"
        )

def main():
    """Main loop: read sensors and check for anomalies every 60 seconds."""
    try:
        while True:
            for pin in SENSOR_PINS:
                temperature, humidity = read_dht22(pin)
                if temperature is not None and humidity is not None:
                    print(f"Pin {pin}: Temp={temperature:.1f}°C, Humidity={humidity:.1f}%")
                    check_anomalies(temperature, humidity, pin)
                else:
                    print(f"Pin {pin}: Read failed after retries.")
            time.sleep(60)
    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
        print(f"Unexpected error: {e}")
    finally:
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

