def log_error(message):
    """Log an error message with a timestamp to error.log."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(ERROR_LOG_FILE, "a") as f:
            f.write(f"{timestamp} - ERROR: {message}\n")
    except Exception as e:
        print(f"Failed to write to error log: {e}")

def log_alert(sensor_id, alert_type, humidity):
    """Log an alert to retail_alerts.log."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(ALERT_LOG_FILE, "a") as f:
            f.write(f"{timestamp} - Sensor {sensor_id}: {alert_type} (Humidity: {humidity:.2f}%)\n")
    except Exception as e:
        log_error(f"Failed to write alert to log: {e}")

def log_cloud_attempt(sensor_id, success):
    """Log a cloud push attempt to cloud_log.log."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    status = "SUCCESS" if success else "FAILURE"
    try:
        with open(CLOUD_LOG_FILE, "a") as f:
            f.write(f"{timestamp} - Sensor {sensor_id}: Cloud push {status}\n")
    except Exception as e:
        log_error(f"Failed to write cloud log: {e}")

def log_data(sensor_id, temperature, humidity):
    """Log sensor data to the daily CSV file with file locking."""
    date_str = datetime.datetime.now().strftime("%Y-%m-%d")
    filename = DATA_LOG_FILE.format(date_str)
    try:
        with open(filename, "a", newline="") as f:
            fcntl.flock(f.fileno(), fcntl.LOCK_EX)
            try:
                writer = csv.writer(f)
                # Write header if file is empty
                if f.tell() == 0:
                    writer.writerow(["Timestamp", "Sensor ID", "Temperature (C)", "Humidity (%)"])
                writer.writerow([datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                                 sensor_id, f"{temperature:.2f}", f"{humidity:.2f}"])
            finally:
                fcntl.flock(f.fileno(), fcntl.LOCK_UN)
    except Exception as e:
        log_error(f"Failed to write data to {filename}: {e}")

def read_sensor(sensor, sensor_id):
    """Read temperature and humidity from a DHT22 sensor with retries."""
    for attempt in range(MAX_RETRIES):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                if 0 <= humidity <= 100 and 0 <= temperature <= 35:
                    return temperature, humidity
                else:
                    log_error(f"Invalid readings from {sensor_id}: Temp={temperature}, Hum={humidity}")
            else:
                log_error(f"None readings from {sensor_id} on attempt {attempt + 1}")
        except RuntimeError as e:
            log_error(f"RuntimeError reading {sensor_id} on attempt {attempt + 1}: {e}")
        except Exception as e:
            log_error(f"Unexpected error reading {sensor_id} on attempt {attempt + 1}: {e}")
        if attempt < MAX_RETRIES - 1:
            time.sleep(RETRY_DELAY)
    log_error(f"Failed to read {sensor_id} after {MAX_RETRIES} attempts")
    return None, None

def send_to_cloud(sensor_id, temperature, humidity):
    """Simulate sending data to a cloud service."""
    success = random.random() < 0.8
    log_cloud_attempt(sensor_id, success)
    if success:
        print(f"Cloud push: Sensor {sensor_id}, Temp={temperature:.2f}, Hum={humidity:.2f}")
    else:
        log_error(f"Cloud push failed for Sensor {sensor_id}")

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize DHT22 sensors
    sensors = {}
    try:
        sensors[DHT_PIN_1] = adafruit_dht.DHT22(DHT_PIN_1, use_pulseio=False)
        sensors[DHT_PIN_2] = adafruit_dht.DHT22(DHT_PIN_2, use_pulseio=False)
    except Exception as e:
        log_error(f"Failed to initialize DHT22 sensors: {e}")
        print("Failed to initialize DHT22 sensors. Check error.log.")
        sys.exit(1)

    print("Starting retail environment monitoring. Press Ctrl+C to exit.")

    try:
        while running:
            now = datetime.datetime.now()
            timestamp = now.strftime("%Y-%m-%d %H:%M:%S")

            for sensor_id, sensor in sensors.items():
                temperature, humidity = read_sensor(sensor, sensor_id)

                if temperature is not None and humidity is not None:
                    log_data(sensor_id, temperature, humidity)
                    send_to_cloud(sensor_id, temperature, humidity)

                    # High humidity alert
                    if humidity > HIGH_HUMIDITY_THRESHOLD:
                        high_humidity_count[sensor_id] += 1
                        low_humidity_count[sensor_id] = 0  # Reset low count
                        if high_humidity_count[sensor_id] >= HIGH_HUMIDITY_ALERT_COUNT:
                            if (last_alert_time[sensor_id][HIGH_HUMIDITY_ALERT_COUNT] is None or
                                (now - last_alert_time[sensor_id][HIGH_HUMIDITY_ALERT_COUNT]).total_seconds() > DEBOUNCE_INTERVAL):
                                log_alert(sensor_id, "High Humidity Alert", humidity)
                                last_alert_time[sensor_id][HIGH_HUMIDITY_ALERT_COUNT] = now
                                high_humidity_count[sensor_id] = 0
                    else:
                        high_humidity_count[sensor_id] = 0

                    # Low humidity alert
                    if humidity < LOW_HUMIDITY_THRESHOLD:
                        low_humidity_count[sensor_id] += 1
                        high_humidity_count[sensor_id] = 0  # Reset high count
                        if low_humidity_count[sensor_id] >= LOW_HUMIDITY_ALERT_COUNT:
                            if (last_alert_time[sensor_id][LOW_HUMIDITY_ALERT_COUNT] is None or
                                (now - last_alert_time[sensor_id][LOW_HUMIDITY_ALERT_COUNT]).total_seconds() > DEBOUNCE_INTERVAL):
                                log_alert(sensor_id, "Low Humidity Alert", humidity)
                                last_alert_time[sensor_id][LOW_HUMIDITY_ALERT_COUNT] = now
                                low_humidity_count[sensor_id] = 0
                    else:
                        low_humidity_count[sensor_id] = 0

            # Wait for next reading interval, but allow early exit
            for _ in range(READING_INTERVAL):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        log_error(f"Unexpected error in main loop: {e}")
    finally:
        for sensor in sensors.values():
            try:
                sensor.exit()
            except Exception:
                pass
        print("GPIO resources released. Exiting.")

if __name__ == "__main__":
    main()

