import time
import logging

import paho.mqtt.client as mqtt
import adafruit_dht
import board

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("dht22_homie")

DEGREE_CELSIUS = "\u00B0C"

running = True
mqtt_client = None
dht_sensor = None


def signal_handler(signum, frame):
    global running
    log.info("Signal %s received, shutting down...", signum)
    running = False


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        log.info("Connected to MQTT broker")
    else:
        log.error("MQTT connection failed with reason code %s", reason_code)


def on_disconnect(client, userdata, flags, reason_code, properties):
    log.info("Disconnected from MQTT broker (reason code %s)", reason_code)


def publish(topic, payload):
    global mqtt_client
    if mqtt_client is None or not mqtt_client.is_connected():
        log.warning("MQTT client not connected; cannot publish to %s", topic)
        return False
    full_topic = f"homie/{config.homieclientid}/{topic}"
    info = mqtt_client.publish(full_topic, str(payload), qos=1)
    info.wait_for_publish(timeout=5)
    return info.rc == mqtt.MQTT_ERR_SUCCESS


def read_dht22():
    global dht_sensor
    if dht_sensor is None:
        log.error("DHT22 sensor not initialized")
        return None, None
    for attempt in range(3):
        try:
            temperature = dht_sensor.temperature
            humidity = dht_sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            log.warning("DHT22 read attempt %d failed: %s", attempt + 1, e)
            time.sleep(2)
        except Exception as e:
            log.error("Unexpected DHT22 error: %s", e)
            break
    return None, None


def publish_sensor_data(temperature, humidity):
    if temperature is not None and humidity is not None:
        publish("temperature", f"{temperature:.1f}{DEGREE_CELSIUS}")
        publish("humidity", f"{humidity:.1f}%")
    else:
        log.warning("Sensor data unavailable; skipping publish")


def main():
    global mqtt_client, dht_sensor

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        mqtt_client = mqtt.Client(
            callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
        )
        mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)
        mqtt_client.on_connect = on_connect
        mqtt_client.on_disconnect = on_disconnect
        mqtt_client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
        mqtt_client.loop_start()
    except Exception as e:
        log.error("Failed to connect to MQTT broker: %s", e)
        sys.exit(1)

    try:
        dht_pin = getattr(board, f"D{config.dhtgpiopin}")
        dht_sensor = adafruit_dht.DHT22(dht_pin, use_pulseio=False)
    except Exception as e:
        log.error("Failed to initialize DHT22 on GPIO %d: %s", config.dhtgpiopin, e)
        mqtt_client.loop_stop()
        mqtt_client.disconnect()
        sys.exit(1)

    log.info("Starting DHT22 Homie MQTT loop (interval=%ds)", config.publishtime)

    try:
        while running:
            temperature, humidity = read_dht22()
            publish_sensor_data(temperature, humidity)
            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        log.error("Unexpected error in main loop: %s", e)
    finally:
        log.info("Cleaning up resources...")
        if mqtt_client is not None:
            mqtt_client.loop_stop()
            mqtt_client.disconnect()
        if dht_sensor is not None:
            try:
                dht_sensor.exit()
            except Exception:
                pass
        log.info("Shutdown complete")


if __name__ == "__main__":
    main()

