import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
READ_INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_sensor_data(serial_connection):
    try:
        raw = serial_connection.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        parts = line.split(',')
        if len(parts) != 2:
            print(f"Malformed data (expected 2 fields): {line!r}")
            return None
        temperature = float(parts[0])
        humidity = float(parts[1])
        return temperature, humidity
    except ValueError as e:
        print(f"ValueError parsing data: {e}")
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}")
        return None

def check_thresholds(temperature, humidity):
    if temperature > TEMP_THRESHOLD:
        print(f"Alert: Temperature {temperature:.1f}°C exceeds threshold {TEMP_THRESHOLD}°C")
    if humidity > HUMIDITY_THRESHOLD:
        print(f"Alert: Humidity {humidity:.1f}% exceeds threshold {HUMIDITY_THRESHOLD}%")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
        sys.exit(1)

    try:
        while _running:
            data = read_sensor_data(serial_connection)
            if data is not None:
                temperature, humidity = data
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                check_thresholds(temperature, humidity)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

