import signal
import sys
import time

from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL = 1.0
PULL_UP = True

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensors = []
    try:
        for pin in SENSOR_PINS:
            try:
                sensor = DigitalInputDevice(pin, pull_up=PULL_UP)
                sensors.append(sensor)
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                return 1
            except Exception as exc:
                print(f"Error: unexpected failure initializing GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        print(f"Monitoring GPIO pins {SENSOR_PINS} (poll every {POLL_INTERVAL:.1f}s). Press Ctrl+C to exit.")

        while _running:
            for idx, pin in enumerate(SENSOR_PINS):
                try:
                    if sensors[idx].is_active:
                        print(f"Response for sensor {idx + 1}")
                except GPIODeviceError as exc:
                    print(f"Warning: read error on GPIO {pin}: {exc}", file=sys.stderr)
                except Exception as exc:
                    print(f"Warning: unexpected error on GPIO {pin}: {exc}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        for sensor in sensors:
            try:
                sensor.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

