        if args:
            send_data(" ".join(args))
        else:
            print("Usage: send <data>")
    elif cmd == "write":
        if args:
            write_direct(" ".join(args))
        else:
            print("Usage: write <data>")
    elif cmd == "exit":
        stop_server()
        sys.exit(0)
    else:
        print("Unknown command. Try 'help'.")


def main():
    """Main entry point."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("Starting DOG server...")
