import RPi.GPIO as GPIO
import time
import requests
import sys

# Configuration
VOLTAGE_PIN = 17
ALERT_URL = 'http://example.com/alert'
POLL_INTERVAL = 1.0
REQUEST_TIMEOUT = 5

def setup_gpio():
    """Initialize GPIO with BCM numbering and configure pin 17 as input with pull-up."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(VOLTAGE_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

def read_voltage_status():
    """Read GPIO pin 17 and return 'Power OK' (HIGH) or 'Power failure' (LOW)."""
    try:
        if GPIO.input(VOLTAGE_PIN) == GPIO.HIGH:
            return "Power OK"
        else:
            return "Power failure"
    except Exception as e:
        print(f"Error reading GPIO pin: {e}", file=sys.stderr)
        return "Error"

def send_alert():
    """Send HTTP POST alert to the configured URL with a 5-second timeout."""
    try:
        response = requests.post(ALERT_URL, json={'alert': 'Power failure detected'}, timeout=REQUEST_TIMEOUT)
        response.raise_for_status()
        print("Alert sent successfully.")
    except requests.exceptions.Timeout:
        print("Error: Request timed out.", file=sys.stderr)
    except requests.exceptions.ConnectionError as e:
        print(f"Error: Connection failed: {e}", file=sys.stderr)
    except requests.exceptions.HTTPError as e:
        print(f"Error: HTTP error: {e}", file=sys.stderr)
    except requests.exceptions.RequestException as e:
        print(f"Error sending alert: {e}", file=sys.stderr)

def main():
    setup_gpio()
    print("Monitoring GPIO pin 17 for voltage status...")
    try:
        while True:
            status = read_voltage_status()
            print(f"Status: {status}")
            if status == "Power failure":
                send_alert()
            time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        print("\nMonitoring stopped by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

