import time
import signal
import sys
import board
import busio
import adafruit_tsl2561
from gpiozero import PWMLED

# Constants
LED_PIN = 18
PWM_FREQUENCY = 1000  # Hz
UPDATE_INTERVAL = 1   # seconds
TSL2561_I2C_ADDRESS = 0x39

# Global flag for graceful shutdown
_running = True

def signal_handler(sig, frame):
    global _running
    _running = False

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c_bus, address=TSL2561_I2C_ADDRESS)
        # Force a read to verify the sensor is actually present
        _ = sensor.lux
        return sensor
    except ValueError as e:
        print(f"TSL2561 sensor not found at address 0x{TSL2561_I2C_ADDRESS:02X}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        return None

def initialize_led(pin, frequency):
    """Initialize the PWM LED."""
    try:
        return PWMLED(pin, frequency=frequency)
    except Exception as e:
        print(f"Error initializing LED on GPIO{pin}: {e}")
        return None

def read_light_intensity(sensor):
    """Read light intensity in lux from the sensor."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light intensity: {e}")
        return None

def map_to_brightness(lux_value):
    """Map lux value (0-10000) to a 0-100 brightness percentage."""
    if lux_value is None:
        return None
    # Clamp lux to a reasonable range for typical indoor/outdoor sensors
    lux_clamped = max(0.0, min(lux_value, 10000.0))
    return (lux_clamped / 100.0)

def set_led_brightness(led, brightness):
    """Set the LED brightness (0.0 to 1.0)."""
    if led is None:
        return
    try:
        led.value = brightness
    except Exception as e:
        print(f"Error setting LED brightness: {e}")

def main():
    """Main function to read light intensity and control LED brightness."""
    global _running

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        sys.exit(1)

    led = initialize_led(LED_PIN, PWM_FREQUENCY)
    if led is None:
        sys.exit(1)

    previous_brightness = 0.0

    try:
        while _running:
            lux = read_light_intensity(light_sensor)

            if lux is not None:
                brightness = map_to_brightness(lux)
                if brightness is not None:
                    previous_brightness = brightness
                else:
                    brightness = previous_brightness
            else:
                print("Sensor read failed; keeping previous LED brightness.")
                brightness = previous_brightness

            set_led_brightness(led, brightness)
            print(f"Lux: {lux:.2f}, LED Brightness: {brightness:.2f}")
            time.sleep(UPDATE_INTERVAL)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        if led is not None:
            led.close()
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

