import signal
import sys
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Constants
LED_GPIO_PIN = 18
TSL2561_I2C_ADDRESS = 0x39
PWM_FREQUENCY = 1000
SLEEP_DURATION = 1
LUX_SCALE_FACTOR = 1000.0

# Global resources for cleanup
i2c_bus = None
led_pwm = None
running = True


def cleanup():
    """Release all hardware resources."""
    global i2c_bus, led_pwm
    if led_pwm is not None:
        try:
            led_pwm.stop()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def initialize_i2c():
    """Initialize the I2C bus on GPIO3 (SCL) / GPIO2 (SDA)."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor at the default address 0x39."""
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c_bus, address=TSL2561_I2C_ADDRESS)
        sensor.gain = adafruit_tsl2561.GAIN_AUTO
        sensor.integration_time = adafruit_tsl2561.INTEGRATIONTIME_402MS
        return sensor
    except ValueError as e:
        print(f"TSL2561 not found at address 0x{TSL2561_I2C_ADDRESS:02X}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing TSL2561: {e}")
        return None


def initialize_pwm(pin, frequency):
    """Initialize PWM on the given BCM pin."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT)
        return GPIO.PWM(pin, frequency)
    except Exception as e:
        print(f"Error initializing PWM on GPIO{pin}: {e}")
        return None


def read_light_level(sensor):
    """Read the light level in lux from the TSL2561."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None


def calculate_brightness(light_level):
    """Map lux to a 0-100 brightness percentage, clamped."""
    if light_level is None:
        return 0.0
