import sys
import time

try:
    import RPi.GPIO as GPIO
    GPIO_AVAILABLE = True
except ImportError:
    GPIO_AVAILABLE = False

# Hardcoded vader_lexicon with at least 20 words
VADER_LEXICON = {
    "great": 0.8, "good": 0.6, "excellent": 0.9, "amazing": 0.95,
    "bad": -0.6, "terrible": -0.8, "awful": -0.7, "horrible": -0.85,
    "love": 0.9, "hate": -0.8, "enjoy": 0.7, "dislike": -0.6,
    "happy": 0.7, "sad": -0.5, "excited": 0.8, "bored": -0.4,
    "smart": 0.6, "dumb": -0.5, "clever": 0.7, "stupid": -0.6,
    "fast": 0.5, "slow": -0.4, "quick": 0.5, "slow": -0.4,
}

GREEN_LED_PIN = 17
RED_LED_PIN = 18
LED_ON_TIME = 2.0

def analyze_sentiment(sentence):
    """Return average sentiment score for a sentence using the vader_lexicon."""
    words = sentence.lower().split()
    scores = [VADER_LEXICON.get(word, 0.0) for word in words]
    if not scores:
        return 0.0
    return sum(scores) / len(scores)

def classify_sentiment(score):
    """Classify sentiment based on average score."""
    if score > 0.2:
        return "Positive"
    elif score < -0.2:
        return "Negative"
    else:
        return "Neutral"

def control_leds(sentiment):
    """Control LEDs based on sentiment. Green for Positive, Red for Negative."""
    if sentiment == "Positive":
        GPIO.output(GREEN_LED_PIN, GPIO.HIGH)
        GPIO.output(RED_LED_PIN, GPIO.LOW)
    elif sentiment == "Negative":
        GPIO.output(GREEN_LED_PIN, GPIO.LOW)
        GPIO.output(RED_LED_PIN, GPIO.HIGH)
    else:
        GPIO.output(GREEN_LED_PIN, GPIO.LOW)
        GPIO.output(RED_LED_PIN, GPIO.LOW)

def main():
    if GPIO_AVAILABLE:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(GREEN_LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(RED_LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    try:
        sentence = input("Enter a sentence: ").strip()
        if not sentence:
            print("No input received.")
            return
        score = analyze_sentiment(sentence)
        sentiment = classify_sentiment(score)
        print(f"Sentiment: {sentiment} (score: {score:.3f})")
        if GPIO_AVAILABLE:
            control_leds(sentiment)
            time.sleep(LED_ON_TIME)
            GPIO.output(GREEN_LED_PIN, GPIO.LOW)
            GPIO.output(RED_LED_PIN, GPIO.LOW)
    except EOFError:
        print("\nInput stream closed.")
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
    finally:
        if GPIO_AVAILABLE:
            GPIO.cleanup()

if __name__ == "__main__":
    main()

