#!/usr/bin/env python3
"""
Beginner line-following robot controller for Raspberry Pi.
Uses two TCRT5000 IR sensors (left on GPIO 5, right on GPIO 6) to detect a black line.
Reads sensors every 0.5 seconds for 10 samples, prints steering decisions.
"""

import RPi.GPIO as GPIO
import time
import sys

# GPIO pins for the two IR sensors (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

# Timing constants
SAMPLE_INTERVAL = 0.5  # seconds between sensor readings
NUM_SAMPLES = 10

def setup_sensors():
    """Configure GPIO pins for the IR sensors."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        sys.exit(1)

def read_sensor(pin):
    """Read a single IR sensor and return 0 (black line) or 1 (white surface)."""
    try:
        return GPIO.input(pin)
    except Exception as e:
        print(f"Error reading sensor on pin {pin}: {e}")
        return 1  # default to white surface on error

def decide_steering(left_state, right_state):
    """
    Decide steering direction based on sensor readings.
    left_state: 0 = black line detected, 1 = white surface
    right_state: 0 = black line detected, 1 = white surface
    """
    if left_state == 0 and right_state == 0:
        return "forward"
    elif left_state == 0 and right_state == 1:
        return "turn-left"
    elif left_state == 1 and right_state == 0:
        return "turn-right"
    else:
        return "search"  # both sensors on white surface

def cleanup():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    """Main loop: read sensors and print steering decisions."""
    setup_sensors()
    try:
        for sample_index in range(NUM_SAMPLES):
            left_state = read_sensor(LEFT_SENSOR_PIN)
            right_state = read_sensor(RIGHT_SENSOR_PIN)
            steering = decide_steering(left_state, right_state)
            print(f"Sample {sample_index + 1}: left={left_state}, right={right_state} -> {steering}")
            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("\nLine-following stopped by user.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

