        self.sub_callbacks[topic] = callback

    def remove_subscription_callback(self, topic: str):
        if topic in self.sub_callbacks:
            del self.sub_callbacks[topic]

    def cleanup(self):
        logger.info("Cleaning up GPIO resources.")
        if self.error_output is not None:
            try:
                if self.pwm and hasattr(self.error_output, 'value'):
                    self.error_output.value = 0.0
                elif not self.pwm and hasattr(self.error_output, 'close'):
                    self.error_output.close()
            except Exception as e:
                logger.error(f"Error during GPIO cleanup: {e}")
            finally:
                self.error_output = None

