import time
import board
import busio
import adafruit_fingerprint

# Constants for I2C address and retry logic
I2C_ADDRESS = 0x26
MAX_INIT_RETRIES = 3
INIT_RETRY_DELAY = 2  # seconds
AUTH_RETRY_DELAY = 1  # seconds


def initialize_fingerprint_sensor():
    """Initializes the fingerprint sensor with robust error handling."""
    i2c_bus = None
    fingerprint_sensor = None

    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None, None

    try:
        for attempt in range(1, MAX_INIT_RETRIES + 1):
            try:
                fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
                print("Fingerprint sensor initialized successfully.")
                return i2c_bus, fingerprint_sensor
            except ValueError as e:
                print(f"I2C bus error (attempt {attempt}/{MAX_INIT_RETRIES}): {e}")
                if attempt < MAX_INIT_RETRIES:
                    time.sleep(INIT_RETRY_DELAY)
            except RuntimeError as e:
                print(f"Sensor not found or unresponsive (attempt {attempt}/{MAX_INIT_RETRIES}): {e}")
                if attempt < MAX_INIT_RETRIES:
                    time.sleep(INIT_RETRY_DELAY)
            except Exception as e:
                print(f"Unexpected error during initialization (attempt {attempt}/{MAX_INIT_RETRIES}): {e}")
                if attempt < MAX_INIT_RETRIES:
                    time.sleep(INIT_RETRY_DELAY)

        print("Failed to initialize fingerprint sensor after multiple attempts.")
        return None, None
    except Exception as e:
        print(f"Fatal error initializing fingerprint sensor: {e}")
        if i2c_bus is not None:
            try:
                i2c_bus.deinit()
            except Exception:
                pass
        return None, None


def authenticate_user(fingerprint_sensor):
    """Authenticates a user by capturing and comparing fingerprint data."""
    try:
        print("Waiting for fingerprint...")
        while True:
            try:
                image_result = fingerprint_sensor.get_image()
                if image_result == adafruit_fingerprint.OK:
                    break
                elif image_result == adafruit_fingerprint.NOFINGER:
                    time.sleep(0.1)
                    continue
                else:
                    print(f"Error getting image: {image_result}")
                    return False
            except RuntimeError as e:
                print(f"I2C communication error during get_image(): {e}")
                return False
            except Exception as e:
                print(f"Unexpected error during get_image(): {e}")
                return False

        print("Templating fingerprint...")
        if fingerprint_sensor.image_2_tz(1) != adafruit_fingerprint.OK:
            print("Error templating fingerprint.")
            return False

        print("Searching fingerprint database...")
        if fingerprint_sensor.finger_search() != adafruit_fingerprint.OK:
            print("Fingerprint not found.")
            return False

        print(f"Access Granted! ID: {fingerprint_sensor.finger_id}, Confidence: {fingerprint_sensor.confidence}")
        return True

    except RuntimeError as e:
        print(f"I2C communication error during authentication: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error during authentication: {e}")
        return False


def main():
    """Main function to run the fingerprint authentication loop."""
    i2c_bus, fingerprint_sensor = initialize_fingerprint_sensor()

    if fingerprint_sensor is None:
        print("Exiting program due to sensor initialization failure.")
        return

    try:
        while True:
            if authenticate_user(fingerprint_sensor):
                # Add code here to grant access (e.g., unlock a door, start a process, etc.)
                pass
            time.sleep(AUTH_RETRY_DELAY)

    except KeyboardInterrupt:
        print("\nExiting program due to keyboard interrupt.")
    finally:
        if i2c_bus is not None:
            try:
                i2c_bus.deinit()
                print("I2C bus deinitialized.")
            except Exception as e:
                print(f"Error deinitializing I2C bus: {e}")


if __name__ == "__main__":
    main()

