import RPi.GPIO as GPIO
import time
import logging
import signal
import threading
from typing import List

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DATA_OUT = 5
TIMER_OUT = 6
DATA_IN = 20
TIMER_IN = 21

START_BYTE = [1, 0, 1, 1, 1, 1, 1, 1]
END_BYTE = [1, 1, 1, 1, 1, 1, 1, 1]
BIT_DELAY = 0.0001

_running = True
_event = threading.Event()


def _signal_handler(signum, frame):
    global _running
    _running = False
    _event.set()


def _cleanup():
    try:
        GPIO.cleanup()
    except Exception:
        pass


def _setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(DATA_OUT, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(TIMER_OUT, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(DATA_IN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    GPIO.setup(TIMER_IN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)


def _list_to_string(bits: List[int]) -> str:
    try:
        return ''.join(map(str, bits))
    except Exception as e:
        logging.error(f"Error converting list to string: {e}")
        return ""


def _string_to_list(char: str) -> List[int]:
    try:
        return [int(bit) for bit in bin(ord(char))[2:].zfill(8)]
    except Exception as e:
        logging.error(f"Error converting string to list: {e}")
        return []


def _list_to_int(bits: List[int]) -> int:
    try:
        return int(_list_to_string(bits), 2)
    except Exception as e:
        logging.error(f"Error converting list to integer: {e}")
        return 0


def _int_to_list(number: int) -> List[int]:
    try:
        return [int(bit) for bit in bin(number)[2:].zfill(8)]
    except Exception as e:
        logging.error(f"Error converting integer to list: {e}")
        return []


def _send_bit(bit: int):
    GPIO.output(TIMER_OUT, GPIO.LOW)
    GPIO.output(DATA_OUT, bit)
    time.sleep(BIT_DELAY)
    GPIO.output(TIMER_OUT, GPIO.HIGH)
    time.sleep(BIT_DELAY)
    GPIO.output(TIMER_OUT, GPIO.LOW)


def send_data(data: str):
    global _running
    _running = True
    try:
        _setup_gpio()
        for bit in START_BYTE:
            _send_bit(bit)
        for char in data:
            if not _running:
                break
            bits = _string_to_list(char)
            for bit in bits:
                if not _running:
                    break
                _send_bit(bit)
        if _running:
            for bit in END_BYTE:
                _send_bit(bit)
        logging.info(f"Sent data: {data}")
    except Exception as e:
        logging.error(f"Error sending data: {e}")
    finally:
        _cleanup()


def _receive_byte():
    global _running
    byte = []
    for _ in range(8):
        if not _running:
            return None
        try:
            while GPIO.input(TIMER_IN) == GPIO.LOW:
                if not _running:
                    return None
            byte.append(GPIO.input(DATA_IN))
            while GPIO.input(TIMER_IN) == GPIO.HIGH:
                if not _running:
                    return None
        except Exception as e:
            logging.error(f"Error receiving bit: {e}")
            return None
    return _list_to_int(byte)


def _receive_data_callback(channel):
    global _running
    if not _running:
        return
    try:
        if GPIO.input(TIMER_IN) == GPIO.HIGH:
            byte = _receive_byte()
            if byte is not None:
                _event.set()
    except Exception as e:
        logging.error(f"Error in receive callback: {e}")


def receive_data(timeout: float = 5.0) -> str:
    global _running
    _running = True
    try:
        _setup_gpio()
        GPIO.add_event_detect(TIMER_IN, GPIO.RISING, callback=_receive_data_callback)
        _event.clear()
        start_time = time.time()
        received_data = ""
        start_received = False
        while _running and (time.time() - start_time) < timeout:
            if _event.is_set():
                byte = _receive_byte()
                if byte is not None:
                    if not start_received and byte == _list_to_int(START_BYTE):
                        start_received = True
                        continue
                    if start_received and byte == _list_to_int(END_BYTE):
                        break
                    if start_received:
                        received_data += chr(byte)
                _event.clear()
        if not _running:
            return ""
        if not start_received:
            logging.warning("Start byte not received.")
            return ""
        if not received_data:
            logging.warning("No data received.")
            return ""
        logging.info(f"Received data: {received_data}")
        return received_data
    except Exception as e:
        logging.error(f"Error receiving data: {e}")
        return ""
    finally:
        _cleanup()


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    send_data("Hello")
    time.sleep(1)
    result = receive_data(5)
    print(result)


if __name__ == "__main__":
    main()

