#!/usr/bin/env python3
# tft144_rpi.py
# Demonstrates a 1.44-inch TFT display (ST7735) on Raspberry Pi.
# Wiring (BCM numbering):
#   CE0  -> GPIO8  (SPI0 CE0)
#   DC   -> GPIO22
#   RST  -> GPIO18
#   LED  -> GPIO23
#   SPI  -> MOSI=GPIO10, SCLK=GPIO11, MISO=GPIO9

import atexit
import signal
import sys
import time

# ---------------------------------------------------------------------------
# Optional imports – stubs used when real libraries/GPIO are unavailable.
# ---------------------------------------------------------------------------
try:
    import spidev
except Exception:
    spidev = None

try:
    from gpiozero import OutputDevice
except Exception:
    OutputDevice = None

try:
    from lib_tft144 import TFT144
except Exception:
    TFT144 = None


class TFTDisplay:
    """Thin wrapper around lib_tft144 with robust error handling and cleanup."""

    def __init__(self, ce_pin=8, dc_pin=22, rst_pin=18, led_pin=23):
        self.spi = None
        self.dc = None
        self.rst = None
        self.led = None
        self.tft = None

        # --- GPIO setup via gpiozero -----------------------------------------
        if OutputDevice is not None:
            try:
                self.led = OutputDevice(led_pin, active_high=True, initial_value=True)
            except Exception as exc:
                raise RuntimeError(f"Failed to init LED GPIO{led_pin}: {exc}") from exc
            try:
                self.rst = OutputDevice(rst_pin, active_high=True, initial_value=True)
            except Exception as exc:
                raise RuntimeError(f"Failed to init RST GPIO{rst_pin}: {exc}") from exc
            try:
                self.dc = OutputDevice(dc_pin, active_high=True, initial_value=False)
            except Exception as exc:
                raise RuntimeError(f"Failed to init DC GPIO{dc_pin}: {exc}") from exc
        else:
            self.led = self.rst = self.dc = None

        # --- SPI setup via spidev --------------------------------------------
        if spidev is not None:
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = 32_000_000
                self.spi.mode = 0
            except Exception as exc:
                raise RuntimeError(f"Failed to open SPI0.0: {exc}") from exc
        else:
            self.spi = None

        # --- lib_tft144 init -------------------------------------------------
        if TFT144 is not None:
            try:
                self.tft = TFT144(
                    self.spi,
                    self.dc,
                    self.rst,
                    self.led,
                    ce_pin,
                    dc_pin,
                    rst_pin,
                    led_pin,
                    TFT144.ORIENTATION90,
                )
            except Exception as exc:
                raise RuntimeError(f"Failed to initialise TFT144: {exc}") from exc
        else:
            self.tft = None

        atexit.register(self.cleanup)

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def cleanup(self):
        """Release SPI and GPIO resources."""
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception:
                pass
            self.spi = None
        if self.led is not None:
            try:
                self.led.close()
            except Exception:
                pass
            self.led = None
        if self.rst is not None:
            try:
                self.rst.close()
            except Exception:
                pass
            self.rst = None
        if self.dc is not None:
            try:
                self.dc.close()
            except Exception:
                pass
            self.dc = None
        self.tft = None

    def display_color_cycle(self):
        """Fill the screen with a rotating palette of colors."""
        colors = [
            self.tft.WHITE,
            self.tft.LIGHTBLUE,
            self.tft.LIGHTGREEN,
            self.tft.LIGHTRED,
            self.tft.LIGHTPINK,
            self.tft.PINK,
            self.tft.MAGENTA,
            self.tft.BLUE,
            self.tft.GREEN,
            self.tft.RED,
            self.tft.BLACK,
        ]
        for color in colors:
            if self.tft is not None:
                self.tft.clear_display(color)
            time.sleep(1)

    def display_character_set(self):
        """Draw printable ASCII (33-126) and extended ASCII (1-255) using fonts 1-8."""
        x_pos = 0
        y_pos = 0
        font_w = 6
        font_h = 8

        for font_num in range(1, 9):
            self.tft.put_char("A", x_pos, y_pos, self.tft.WHITE, self.tft.BLACK, font_num)
            x_pos += font_w
            if x_pos + font_w > 128:
                x_pos = 0
                y_pos += font_h
            if y_pos + font_h > 128:
                break

        for font_num in (3, 4):
            x_pos = 0
            y_pos = 24
            for char_code in range(1, 256):
                try:
                    self.tft.put_char(
                        chr(char_code), x_pos, y_pos, self.tft.WHITE, self.tft.BLACK, font_num
                    )
                except Exception:
                    pass
                x_pos += font_w
                if x_pos + font_w > 128:
                    x_pos = 0
                    y_pos += font_h
                if y_pos + font_h > 128:
                    break

    def display_strings(self):
        """Show 'Quick Brown fox jumped over' at different fonts and colors."""
        self.tft.put_string("Quick Brown fox jumped over", 0, 0, self.tft.WHITE, self.tft.BLACK)
        self.tft.put_string("Quick Brown fox jumped over", 0, 24, self.tft.LIGHTBLUE, self.tft.BLACK, 1)
        self.tft.put_string("Quick Brown fox jumped over", 0, 48, self.tft.LIGHTGREEN, self.tft.BLACK, 2)
