# tft144_rpi.py
# Demonstrates a 1.44-inch TFT display (ST7735) on Raspberry Pi.
# Wiring (BCM numbering):
#   CE0  -> GPIO8  (SPI0 CE0)
#   DC   -> GPIO22
#   RST  -> GPIO18
#   LED  -> GPIO23
#   SPI  -> MOSI=GPIO10, SCLK=GPIO11, MISO=GPIO9

import atexit
import signal
import sys
import time

# ---------------------------------------------------------------------------
# Optional imports – stubs used when real libraries/GPIO are unavailable.
# ---------------------------------------------------------------------------
try:
    import spidev
except Exception:
    spidev = None

try:
    from gpiozero import OutputDevice
except Exception:
    OutputDevice = None

try:
    from lib_tft144 import TFT144
except Exception:
    TFT144 = None


class TFTDisplay:
    """Thin wrapper around lib_tft144 with robust error handling and cleanup."""

    def __init__(self, ce_pin=8, dc_pin=22, rst_pin=18, led_pin=23):
        self.spi = None
        self.dc = None
        self.rst = None
        self.led = None
        self.tft = None

        # --- GPIO setup via gpiozero -----------------------------------------
        if OutputDevice is not None:
            try:
                self.led = OutputDevice(led_pin, active_high=True, initial_value=True)
            except Exception as exc:
                raise RuntimeError(f"Failed to init LED GPIO{led_pin}: {exc}") from exc
            try:
                self.rst = OutputDevice(rst_pin, active_high=True, initial_value=True)
            except Exception as exc:
                raise RuntimeError(f"Failed to init RST GPIO{rst_pin}: {exc}") from exc
            try:
                self.dc = OutputDevice(dc_pin, active_high=True, initial_value=False)
            except Exception as exc:
                raise RuntimeError(f"Failed to init DC GPIO{dc_pin}: {exc}") from exc
        else:
            self.led = self.rst = self.dc = None

        # --- SPI setup via spidev --------------------------------------------
        if spidev is not None:
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = 32_000_000
                self.spi.mode = 0
            except Exception as exc:
                raise RuntimeError(f"Failed to open SPI0.0: {exc}") from exc
        else:
            self.spi = None

        # --- lib_tft144 init -------------------------------------------------
        if TFT144 is not None:
            try:
                self.tft = TFT144(
                    self.spi,
                    self.dc,
                    self.rst,
                    self.led,
                    ce_pin,
                    dc_pin,
                    rst_pin,
                    led_pin,
                    TFT144.ORIENTATION90,
