import signal
import sys
import time

from gpiozero import Button, LED
from gpiozero.exc import DeviceClosed, BadPinFactory

DOOR_PIN = 19
SIREN_PIN = 26
SAMPLE_INTERVAL = 0.4
NUM_SAMPLES = 8
BOUNCE_TIME = 0.05

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        reed = Button(DOOR_PIN, pull_up=False, bounce_time=BOUNCE_TIME)
        siren = LED(SIREN_PIN)
    except BadPinFactory as e:
        print(f"GPIO library unavailable: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Failed to initialize GPIO devices: {e}", file=sys.stderr)
        sys.exit(1)

    siren.on()
    print("Home security system armed. Monitoring door...")

    try:
        for i in range(NUM_SAMPLES):
            if not _running:
                break
            try:
                door_open = not reed.is_pressed
            except DeviceClosed:
                print("Reed switch device closed unexpectedly.", file=sys.stderr)
                break
            except Exception as e:
                print(f"Error reading reed switch: {e}", file=sys.stderr)
                break

            if door_open:
                siren.on()
                print(f"Alarm triggered! Door opened (sample {i + 1}/{NUM_SAMPLES}).")
            else:
                siren.off()

            time.sleep(SAMPLE_INTERVAL)

        if _running:
            print("Monitoring complete.")
    finally:
        try:
            siren.off()
            siren.close()
        except Exception:
            pass
        try:
            reed.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

