import sys
import signal

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("Error: gpiozero library is required. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

FAN_PIN = 12
PWM_FREQUENCY = 25000  # 25 kHz, standard for 4-wire PWM fans

fan = None
running = True

def cleanup():
    global fan
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
        fan = None

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

try:
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY, initial_value=0)
    except Exception as e:
        print(f"Warning: Failed to initialize hardware PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        print("Falling back to software PWM.", file=sys.stderr)
        try:
            fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY, initial_value=0, pin_factory=None)
        except Exception as e2:
            print(f"Error: Failed to initialize PWM on GPIO{FAN_PIN}: {e2}", file=sys.stderr)
            sys.exit(1)

    while running:
        try:
            user_input = input("Enter fan speed (0-100, or 'q' to quit): ")
        except EOFError:
            break

        if user_input.lower() == 'q':
            break

        try:
            speed = float(user_input)
            if 0 <= speed <= 100:
                fan.value = speed / 100.0
                print(f"Fan speed set to {speed:.1f}%")
            else:
                print("Invalid input. Please enter a number between 0 and 100.")
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100.")

except Exception as e:
    print(f"An unexpected error occurred: {e}", file=sys.stderr)

finally:
    cleanup()
    print("Fan control stopped. GPIO resources released.")

