#!/usr/bin/env python3
"""3-bit binary counter controlled by Pimoroni Rainbow HAT touchpads.

Touchpads A, B, C on the Rainbow HAT correspond to GPIO5, GPIO6, GPIO12
respectively.  Each press toggles the corresponding bit (MSB = A, LSB = C).
The three onboard discrete LEDs (green on GPIO7, blue on GPIO8) reflect the
bit states.  The HT16K33 14-segment display at I2C 0x70 shows the decimal
value (0-7).  The APA102 LED strip (data GPIO10, clock GPIO11) shows a
single white pixel at the value index when 0-6, dim white at index 0 when
7, and all 7 white when 7.  A piezo buzzer on GPIO13 plays MIDI note 60 +
value (C4 + value).

Requires: gpiozero, adafruit-blinka, adafruit-circuitpython-ht16k33,
         adafruit-circuitpython-apa102, adafruit-circuitpython-dotstar.
"""

import signal
import sys
import time
import logging

import board
import digitalio
import pulseio

try:
    from adafruit_ht16k33.segments import Seg14x4
except Exception:
    Seg14x4 = None

try:
    import adafruit_apa102
except Exception:
    adafruit_apa102 = None

try:
    from gpiozero import Button, LED, Buzzer
except Exception:
    Button = None
    LED = None
    Buzzer = None

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("rainbow_counter")

# ---------------------------------------------------------------------------
# Pin / bit mapping
# ---------------------------------------------------------------------------
TOUCH_PINS = [board.D5, board.D6, board.D12]   # A, B, C
LED_PINS = [board.D7, board.D8]                # green, blue
BUZZER_PIN = board.D13
STRIP_DATA_PIN = board.D10
STRIP_CLOCK_PIN = board.D11
DISPLAY_I2C_ADDR = 0x70

MIDI_BASE = 60
DIM_WHITE = 0x10
WHITE = 0xFF

# ---------------------------------------------------------------------------
# Globals (initialised in main)
# ---------------------------------------------------------------------------
touch_buttons = []
discrete_leds = []
apa_strip = None
display = None
buzzer = None
running = True


def bit_value(bit_index: int) -> int:
    """Return the decimal value (0-7) from the three bit states."""
    return sum(1 << i if s else 0 for i, s in enumerate(bit_states))


def update_display() -> None:
    """Push the current decimal value to the HT16K33 14-segment display."""
    if display is None:
        return
    try:
        display.fill(0)
        display.print(str(bit_value(0)))
        display.show()
    except Exception as exc:
        log.error("Display update failed: %s", exc)


def update_leds() -> None:
    """Drive the three discrete LEDs from the bit states."""
    if not discrete_leds:
        return
    try:
        discrete_leds[0].value = bit_states[1]  # B -> green
        discrete_leds[1].value = bit_states[2]  # C -> blue
    except Exception as exc:
        log.error("LED update failed: %s", exc)


def update_strip() -> None:
    """Drive the APA102 LED strip according to the current value."""
    global apa_strip
    if apa_strip is None:
        return
    try:
        n = bit_value(0)
        if apa_strip is not None:
            apa_strip.fill(0)
            if n == 7:
                for i in range(7):
                    apa_strip[i] = (DIM_WHITE, DIM_WHITE, DIM_WHITE)
            elif n == 0:
                apa_strip[0] = (DIM_WHITE, DIM_WHITE, DIM_WHITE)
            else:
                r = DIM_WHITE if bit_states[0] else 0
                g = DIM_WHITE if bit_states[1] else 0
                b = DIM_WHITE if bit_states[2] else 0
                apa_strip[n] = (r, g, b)
            apa_strip.show()
    except Exception as exc:
        log.error("Strip update failed: %s", exc)


def play_tone() -> None:
    """Play a 0.5 s tone on the piezo buzzer at MIDI note 60 + value."""
    if buzzer is None:
        return
    try:
        freq = 2 ** ((bit_value(0) + MIDI_BASE - 69) / 12.0) * 440.0
        buzzer.frequency = int(freq)
        buzzer.on()
        time.sleep(0.5)
        buzzer.off()
    except Exception as exc:
        log.error("Tone playback failed: %s", exc)


def on_touch(channel: int) -> None:
    """Callback for a touchpad press: toggle the corresponding bit."""
    if 0 <= channel < len(bit_states):
        bit_states[channel] = not bit_states[channel]
        update_leds()
        update_display()
        update_strip()
        play_tone()


def cleanup() -> None:
    """Release all hardware resources cleanly."""
    global running
    running = False
    log.info("Cleaning up...")
    try:
        if apa_strip is not None:
            apa_strip.fill(0)
            apa_strip.show()
    except Exception:
        pass
    try:
        if display is not None:
            display.fill(0)
            display.show()
    except Exception:
        pass
    for led in discrete_leds:
        try:
            led.off()
        except Exception:
            pass
    for btn in touch_buttons:
        try:
            btn.close()
        except Exception:
            pass
    try:
        if buzzer is not None:
            buzzer.off()
            buzzer.close()
    except Exception:
        pass
    log.info("Cleanup complete.")


def signal_handler(signum, frame) -> None:
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    log.info("Signal %s received, shutting down.", signum)
    cleanup()
    sys.exit(0)


def main() -> None:
    global touch_buttons, discrete_leds, apa_strip, display, buzzer

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bit_states = [False, False, False]

    # --- Touchpads ----------------------------------------------------------
    if Button is not None:
        for i, pin in enumerate(TOUCH_PINS):
            try:
                btn = Button(pin, pull_up=True, bounce_time=0.05)
                btn.when_pressed = lambda ch=i: on_touch(ch)
                touch_buttons.append(btn)
            except Exception as exc:
                log.error("Touchpad on GPIO%d init failed: %s", pin, exc)
    else:
        log.warning("gpiozero unavailable; touchpad callbacks disabled.")

    # --- Discrete LEDs ------------------------------------------------------
    if LED is not None:
        for pin in LED_PINS:
            try:
                discrete_leds.append(LED(pin))
            except Exception as exc:
                log.error("LED on GPIO%d init failed: %s", pin, exc)
    else:
        log.warning("gpiozero unavailable; discrete LEDs disabled.")

    # --- APA102 LED strip ---------------------------------------------------
    if adafruit_apa102 is not None:
        try:
            apa_strip = adafruit_apa102.APA102(
                pixels=7, data_pin=STRIP_DATA_PIN, clock_pin=STRIP_CLOCK_PIN
            )
            apa_strip.fill(0)
            apa_strip.show()
        except Exception as exc:
            log.error("APA102 init failed: %s", exc)
            apa_strip = None
    else:
        log.warning("adafruit-circuitpython-apa102 unavailable; strip disabled.")

    # --- 14-segment display -------------------------------------------------
    if Seg14x4 is not None:
        try:
            i2c = digitalio.I2C(board.SCL, board.SDA)
            display = Seg14x4(i2c, address=DISPLAY_I2C_ADDR)
            display.brightness = 0.5
            display.fill(0)
            display.show()
        except Exception as exc:
            log.error("HT16K33 display init failed: %s", exc)
            display = None
    else:
        log.warning("adafruit-circuitpython-ht16k33 unavailable; display disabled.")

    # --- Piezo buzzer -------------------------------------------------------
    if Buzzer is not None:
        try:
            buzzer = Buzzer(BUZZER_PIN)
        except Exception as exc:
            log.error("Buzzer init failed: %s", exc)
            buzzer = None
    else:
        log.warning("gpiozero unavailable; buzzer disabled.")

    log.info("Rainbow counter ready.  Press Ctrl-C to exit.")
    try:
        signal.pause()
    except Exception:
        pass


if __name__ == "__main__":
    main()

