    """Transcribe a simulated audio frame energy into a command keyword."""
    keyword_map = {0: 'water', 1: 'stop', 2: 'status'}
    return keyword_map[frame_energy % 3]


def map_to_action(keyword):
    """Map a recognized keyword to a farm action."""
    action_map = {'water': 'open_valve', 'stop': 'close_valve', 'status': 'report'}
    return action_map.get(keyword, 'unknown')


