import time
import logging
import signal
import sys
from gpiozero import Motor, DigitalOutputDevice, Device
from gpiozero.pins.pigpio import PiGPIOFactory

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

LEFT_MOTOR_FORWARD_PIN = 17
LEFT_MOTOR_BACKWARD_PIN = 18
RIGHT_MOTOR_FORWARD_PIN = 22
RIGHT_MOTOR_BACKWARD_PIN = 23
L298N_ENABLE_A_PIN = 12
L298N_ENABLE_B_PIN = 13

TILT_THRESHOLD = 20.0
DRIVE_DURATION = 0.5


class ChassisController:
    def __init__(self):
        self.left_motor = None
        self.right_motor = None
        self.enable_a = None
        self.enable_b = None
        self._initialized = False
        try:
            factory = PiGPIOFactory()
            self.left_motor = Motor(
                forward=LEFT_MOTOR_FORWARD_PIN,
                backward=LEFT_MOTOR_BACKWARD_PIN,
                pin_factory=factory
            )
            self.right_motor = Motor(
                forward=RIGHT_MOTOR_FORWARD_PIN,
                backward=RIGHT_MOTOR_BACKWARD_PIN,
                pin_factory=factory
            )
            self.enable_a = DigitalOutputDevice(L298N_ENABLE_A_PIN, pin_factory=factory)
            self.enable_b = DigitalOutputDevice(L298N_ENABLE_B_PIN, pin_factory=factory)
            self.enable_a.on()
            self.enable_b.on()
            self._initialized = True
            logging.info("Chassis controller initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize chassis controller: {e}")
            self.cleanup()
            raise

    def drive_forward(self, speed_fraction):
        if not self._initialized:
            logging.error("Chassis controller not initialized.")
            return
        try:
            self.left_motor.forward(speed_fraction)
            self.right_motor.forward(speed_fraction)
            logging.info(f"Driving forward at speed {speed_fraction}")
        except Exception as e:
            logging.error(f"Error driving forward: {e}")

    def turn_left(self, speed_fraction):
        if not self._initialized:
            logging.error("Chassis controller not initialized.")
            return
        try:
            self.left_motor.forward(speed_fraction)
            self.right_motor.backward(speed_fraction)
            logging.info(f"Turning left at speed {speed_fraction}")
        except Exception as e:
            logging.error(f"Error turning left: {e}")

    def turn_right(self, speed_fraction):
        if not self._initialized:
            logging.error("Chassis controller not initialized.")
            return
        try:
            self.left_motor.backward(speed_fraction)
            self.right_motor.forward(speed_fraction)
            logging.info(f"Turning right at speed {speed_fraction}")
        except Exception as e:
            logging.error(f"Error turning right: {e}")

    def stop_all(self):
        if not self._initialized:
            logging.error("Chassis controller not initialized.")
            return
        try:
            self.left_motor.stop()
            self.right_motor.stop()
            logging.info("All motors stopped.")
        except Exception as e:
            logging.error(f"Error stopping motors: {e}")

    def cleanup(self):
        if self._initialized:
            self.stop_all()
            for dev in [self.enable_a, self.enable_b, self.left_motor, self.right_motor]:
                if dev is not None:
                    try:
                        dev.close()
                    except Exception:
                        pass
            self._initialized = False
            logging.info("GPIO cleanup completed.")


def signal_handler(signum, frame):
    logging.info(f"Signal {signum} received, shutting down.")
    if 'chassis' in globals() and chassis is not None:
        chassis.cleanup()
    sys.exit(0)


def main():
    global chassis
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    chassis = None
    try:
        chassis = ChassisController()
        tilt_readings = [25, -25, 0, 30, -15, 40, -30, 10]
        for tilt_angle in tilt_readings:
            logging.info(f"Current tilt angle: {tilt_angle}")
            if tilt_angle > TILT_THRESHOLD:
                chassis.drive_forward(0.5)
                time.sleep(DRIVE_DURATION)
            elif tilt_angle < -TILT_THRESHOLD:
                chassis.turn_left(0.5)
                time.sleep(DRIVE_DURATION)
            else:
                chassis.stop_all()
                time.sleep(0.1)
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        if chassis is not None:
            chassis.cleanup()


if __name__ == "__main__":
    main()

