import random
import time
import signal
import sys
from gpiozero import LED
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# Constants
LED_PIN = 18
THRESHOLD = 50
NUM_READINGS = 5
DELAY_SECONDS = 2
SENSOR_FAILURE_RATE = 0.1

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def simulate_water_quality():
    """Simulate a water quality reading as a percentage (0-100)."""
    if random.random() < SENSOR_FAILURE_RATE:
        print("Sensor read failed (simulated). Retrying...")
        time.sleep(0.5)
        if random.random() < SENSOR_FAILURE_RATE:
            print("Sensor read failed again. Using fallback value.")
            return 50
        return random.randint(0, 100)
    return random.randint(0, 100)


def main():
    """Main function to simulate water quality monitoring."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    led = None
    try:
        # Initialize LED with error handling
        try:
            led = LED(LED_PIN)
            print(f"LED initialized on GPIO{LED_PIN} (BCM).")
        except (GPIOZeroError, GPIODeviceError) as e:
            print(f"Error initializing LED on GPIO{LED_PIN}: {e}")
            sys.exit(1)
        except Exception as e:
            print(f"Unexpected error initializing LED: {e}")
            sys.exit(1)

        readings_taken = 0
        while _running and readings_taken < NUM_READINGS:
            try:
                water_quality = simulate_water_quality()
                readings_taken += 1
                print(f"Reading {readings_taken}/{NUM_READINGS} - Water Quality: {water_quality}%")

                if water_quality < THRESHOLD:
                    led.on()
                    print("  -> Water quality below threshold. LED ON.")
                else:
                    led.off()
                    print("  -> Water quality normal. LED OFF.")

            except (GPIOZeroError, GPIODeviceError) as e:
                print(f"GPIO error during reading {readings_taken}: {e}")
            except Exception as e:
                print(f"Unexpected error during reading {readings_taken}: {e}")

            # Wait for the next reading, but allow early exit on signal
            if readings_taken < NUM_READINGS and _running:
                time.sleep(DELAY_SECONDS)

        if not _running:
            print("\nShutdown requested. Exiting gracefully.")
        else:
            print("Water quality monitoring complete.")

    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        # Clean resource release on all exit paths
        if led is not None:
            try:
                led.close()
                print("LED resource released.")
            except Exception as e:
                print(f"Error releasing LED resource: {e}")
        print("Program terminated.")


if __name__ == "__main__":
    main()

