import time
import signal
import sys
import board
import busio
import adafruit_tcs34725
from PIL import Image

# Global resources for cleanup
i2c_bus = None
color_sensor = None
running = True

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global i2c_bus, color_sensor
    if color_sensor is not None:
        try:
            color_sensor.deinit()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass

def get_sensor_color_data():
    """Reads color data from the TCS34725 sensor and returns (R, G, B, Clear)."""
    global color_sensor
    try:
        r, g, b = color_sensor.color_rgb_bytes
        clear = color_sensor.color
        return (r, g, b, clear)
    except Exception as e:
        print(f"Error reading color sensor data: {e}", file=sys.stderr)
        return (0, 0, 0, 0)

def find_dominant_image_color(image_path):
    """Finds the dominant color in an image file using Pillow."""
    try:
        with Image.open(image_path) as img:
            img = img.resize((100, 100))
            colors = img.getcolors(1000000)
            if colors:
                dominant_color = max(colors, key=lambda item: item[0])[1]
                return dominant_color
            return (0, 0, 0)
    except FileNotFoundError:
        print(f"Error: Image file not found at {image_path}", file=sys.stderr)
        return (0, 0, 0)
    except Exception as e:
        print(f"Error processing image: {e}", file=sys.stderr)
        return (0, 0, 0)

def main():
    global i2c_bus, color_sensor, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        color_sensor = adafruit_tcs34725.TCS34725(i2c_bus)
        color_sensor.integration_time = adafruit_tcs34725.INTEGRATION_TIME_50MS
        color_sensor.gain = adafruit_tcs34725.GAIN_4X
    except Exception as e:
        print(f"Error initializing TCS34725 sensor: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while running:
            sensor_data = get_sensor_color_data()
            dominant_color = find_dominant_image_color("image.jpg")

            print(f"Sensor Data: R={sensor_data[0]}, G={sensor_data[1]}, B={sensor_data[2]}, Clear={sensor_data[3]}")
            print(f"Dominant Color: R={dominant_color[0]}, G={dominant_color[1]}, B={dominant_color[2]}")

            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

