from gpiozero.exc import GPIOZeroError, GPIODeviceError

DOOR_LOCK_PIN = 27
UNLOCK_DURATION = 5.0
LOOP_DELAY = 0.1

_running = True
_lock = None


def _handle_signal(signum, frame):
    global _running
    _running = False


def initialize_gpio(pin):
    try:
        return OutputDevice(pin, active_high=True, initial_value=False)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error initializing GPIO pin {pin}: {exc}", file=sys.stderr)
        return None
    except Exception as exc:
        print(f"Unexpected error initializing GPIO pin {pin}: {exc}", file=sys.stderr)
        return None


def lock_door(lock):
    if lock is None:
        return False
    try:
        lock.off()
        return True
    except Exception as exc:
        print(f"Error locking door: {exc}", file=sys.stderr)
        return False


def unlock_door(lock, duration):
    if lock is None:
        return False
    try:
        lock.on()
        time.sleep(duration)
        lock.off()
        return True
    except Exception as exc:
        print(f"Error unlocking door: {exc}", file=sys.stderr)
        return False


def main():
    global _lock

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    _lock = initialize_gpio(DOOR_LOCK_PIN)
    if _lock is None:
        sys.exit(1)

    if not lock_door(_lock):
        sys.exit(1)

    print("Door locked. Starting main loop...")

    try:
        while _running:
            authorization_status = True
            if authorization_status:
                print("Authorization granted. Unlocking door...")
                if not unlock_door(_lock, UNLOCK_DURATION):
                    print("Failed to unlock door.", file=sys.stderr)
            time.sleep(LOOP_DELAY)
    finally:
        if _lock is not None:
            try:
                _lock.off()
            except Exception:
                pass
            _lock.close()
        print("GPIO cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

