from gpiozero import LED
from gpiozero.exc import GPIOZeroError

LED_PIN = 23
MOISTURE_THRESHOLD = 30
NUM_READINGS = 3
WATERING_DURATION = 2.0
DELAY_BETWEEN_READINGS = 1.0


def read_moisture_level():
    """Simulate reading a moisture sensor and return a random integer 0-100."""
    return random.randint(0, 100)


def control_watering_system(led, moisture_level):
    """Turn the LED on for WATERING_DURATION seconds if moisture is below threshold."""
    if moisture_level < MOISTURE_THRESHOLD:
        print(f"Moisture level {moisture_level}% is below threshold. Watering...")
        led.on()
        time.sleep(WATERING_DURATION)
        led.off()
        print("Watering complete.")
    else:
        print(f"Moisture level {moisture_level}% is sufficient.")


def main():
    """Main loop: read moisture NUM_READINGS times and control the watering system."""
    try:
        with LED(LED_PIN) as led:
            for i in range(NUM_READINGS):
                moisture = read_moisture_level()
                print(f"Reading {i + 1}/{NUM_READINGS}: Moisture level = {moisture}%")
                control_watering_system(led, moisture)
                if i < NUM_READINGS - 1:
                    time.sleep(DELAY_BETWEEN_READINGS)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user. Shutting down.")
    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}")
    except Exception as exc:
        print(f"Unexpected error: {exc}")
    finally:
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

