#!/usr/bin/env python3
"""
Automated Chicken Coop Door Controller

Controls a relay on GPIO 17 (BCM) to simulate an automated chicken coop door.
Door opens (relay LOW) between 7:00 AM and 7:00 PM, inclusive.
"""

import RPi.GPIO as GPIO
import time
import datetime
import sys

# Configuration
RELAY_PIN = 17
SUNRISE_HOUR = 7
SUNSET_HOUR = 19
CHECK_INTERVAL = 60  # seconds

def setup_gpio():
    """Initialize GPIO pin as output, default HIGH (door closed)."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.HIGH)
    except RuntimeError as e:
        print(f"Error: GPIO setup failed - {e}", file=sys.stderr)
        sys.exit(1)

def set_door_state(open_state):
    """Set relay state: LOW = open, HIGH = closed."""
    if open_state:
        GPIO.output(RELAY_PIN, GPIO.LOW)
        print("Door opened (relay LOW)")
    else:
        GPIO.output(RELAY_PIN, GPIO.HIGH)
        print("Door closed (relay HIGH)")

def main():
    setup_gpio()
    sunrise_time = datetime.time(SUNRISE_HOUR, 0, 0)
    sunset_time = datetime.time(SUNSET_HOUR, 0, 0)

    print("Chicken coop door controller started. Press Ctrl+C to exit.")

    try:
        while True:
            now = datetime.datetime.now().time()
            if sunrise_time <= now <= sunset_time:
                if GPIO.input(RELAY_PIN) != GPIO.LOW:
                    set_door_state(True)
            else:
                if GPIO.input(RELAY_PIN) != GPIO.HIGH:
                    set_door_state(False)
            time.sleep(CHECK_INTERVAL)
    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        GPIO.cleanup()
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

