import signal
import sys
import time

from gpiozero import AngularServo
from gpiozero.exc import OutputDeviceBadValue, GPIODeviceError


class RoboticArm:
    """Control a three-joint robotic arm using three SG90 servos on a Raspberry Pi."""

    SERVO_MIN_PULSE_WIDTH = 0.5 / 1000.0   # 0.5 ms
    SERVO_MAX_PULSE_WIDTH = 2.5 / 1000.0   # 2.5 ms
    SERVO_MAX_ANGLE = 90
    SETTLING_DELAY = 0.4

    def __init__(self, base_pin, shoulder_pin, gripper_pin):
        """Initialize the three servo joints with shared pulse-width limits."""
        try:
            self.base_servo = AngularServo(
                base_pin,
                min_angle=-self.SERVO_MAX_ANGLE,
                max_angle=self.SERVO_MAX_ANGLE,
                min_pulse_width=self.SERVO_MIN_PULSE_WIDTH,
                max_pulse_width=self.SERVO_MAX_PULSE_WIDTH,
                frame_width=20 / 1000.0,
            )
            self.shoulder_servo = AngularServo(
                shoulder_pin,
                min_angle=-self.SERVO_MAX_ANGLE,
                max_angle=self.SERVO_MAX_ANGLE,
                min_pulse_width=self.SERVO_MIN_PULSE_WIDTH,
                max_pulse_width=self.SERVO_MAX_PULSE_WIDTH,
                frame_width=20 / 1000.0,
            )
            self.gripper_servo = AngularServo(
                gripper_pin,
                min_angle=-self.SERVO_MAX_ANGLE,
                max_angle=self.SERVO_MAX_ANGLE,
                min_pulse_width=self.SERVO_MIN_PULSE_WIDTH,
                max_pulse_width=self.SERVO_MAX_PULSE_WIDTH,
                frame_width=20 / 1000.0,
            )
        except GPIODeviceError as exc:
            raise RuntimeError(f"Failed to initialize servos: {exc}") from exc

    def move_joint(self, servo, target_angle):
        """Move a single servo to a clamped target angle and wait for settling."""
        clamped = max(-self.SERVO_MAX_ANGLE, min(self.SERVO_MAX_ANGLE, target_angle))
        try:
            servo.angle = clamped
        except OutputDeviceBadValue as exc:
            print(f"Invalid angle {target_angle} for servo; skipping: {exc}")
            return
        time.sleep(self.SETTLING_DELAY)

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        """Move all three joints sequentially to the requested pose."""
        self.move_joint(self.base_servo, base_angle)
        self.move_joint(self.shoulder_servo, shoulder_angle)
        self.move_joint(self.gripper_servo, gripper_angle)

    def release(self):
        """Detach all servos (set angle=None) to stop PWM signals."""
        for servo in (self.base_servo, self.shoulder_servo, self.gripper_servo):
            try:
                servo.angle = None
            except Exception:
                pass

    def cleanup(self):
        """Release servos and close GPIO resources."""
        self.release()
        for servo in (self.base_servo, self.shoulder_servo, self.gripper_servo):
            try:
                servo.close()
            except Exception:
                pass


def run_demo_sequence(robot_arm):
    """Execute a short demonstration sequence of poses."""
    pose_sequence = [(0, 0, 0), (45, -30, 20), (-45, 30, -20), (0, 0, 0)]
    for base_angle, shoulder_angle, gripper_angle in pose_sequence:
        print(f"Moving to pose ({base_angle}, {shoulder_angle}, {gripper_angle})")
        robot_arm.go_to_pose(base_angle, shoulder_angle, gripper_angle)


def main():
    arm = None
    try:
        arm = RoboticArm(base_pin=17, shoulder_pin=27, gripper_pin=22)
        run_demo_sequence(arm)
    except ValueError as exc:
        print(f"Pin conflict: {exc}")
    except OutputDeviceBadValue as exc:
        print(f"Invalid angle: {exc}")
    except RuntimeError as exc:
        print(f"Runtime error: {exc}")
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if arm is not None:
            arm.cleanup()


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}; exiting.")
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    main()

