import signal
import sys
import logging
from typing import Dict, Any, Optional

import serial
from pymodbus.client import ModbusSerialClient
from pymodbus.exceptions import ModbusIOException, ModbusException
from pymodbus.payload import BinaryPayloadDecoder
from pymodbus.constants import Endian

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class Servo:
    """
    A class to control a servo motor via Modbus RTU over a Raspberry Pi UART.
    """

    # --- Register Map ---
    REGISTERS: Dict[str, Dict[str, Any]] = {
        "STATUS": {"R/W": "R", "Register": 0x3000, "functioncode": 3},
        "CONTROL": {"R/W": "W", "Register": 0x3100, "functioncode": 6, "Value": {"Stop": 0x0006, "Start": 0x000F}},
        "OPMODE": {"R/W": "W", "Register": 0x3500, "functioncode": 6, "Value": {"Position": 1}},
        "VelocityCommand": {"R/W": "W", "Register": 0x6F00, "functioncode": 16, "write_length": 2},
        "VelocityFeedback": {"R/W": "R", "Register": 0x3B00, "functioncode": 3, "read_length": 2},
        "PositionCommand": {"R/W": "W", "Register": 0x4000, "functioncode": 16, "write_length": 2},
        "PositionFeedback": {"R/W": "R", "Register": 0x3700, "functioncode": 3, "read_length": 2},
    }

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 115200, timeout: float = 1.0):
        self._client: Optional[ModbusSerialClient] = None
        self._connected: bool = False
        self._shutdown: bool = False

        try:
            self._client = ModbusSerialClient(
                port=port,
                baudrate=baudrate,
                bytesize=8,
                parity='N',
                stopbits=1,
                timeout=timeout,
            )
