import time
import signal
import sys
from gpiozero import OutputDevice, Servo
from gpiozero.exc import GPIOZeroError, DeviceClosed

# GPIO pin definitions (BCM numbering)
LASER_PIN = 17
HORIZONTAL_PIN = 18
VERTICAL_PIN = 19

# Servo pulse-width mapping: 0.0 (min) -> 1.0 (max)
# These values are typical for a standard gpiozero Servo (min/max pulse widths)
HORIZONTAL_PULSE_WIDTHS = [0.0, 0.02, 0.04, 0.06, 0.08, 0.10, 0.12, 0.14, 0.16, 0.18]
VERTICAL_PULSE_WIDTHS = [0.0, 0.02, 0.04, 0.06, 0.08, 0.10, 0.12, 0.14, 0.16, 0.18]

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


class Laser:
    """Controls a laser module via a GPIO pin using gpiozero."""

    def __init__(self, pin=LASER_PIN):
        self.pin = pin
        self.device = None
        try:
            self.device = OutputDevice(pin, active_high=True, initial_value=False)
        except GPIOZeroError as e:
            print(f"Error initializing laser on GPIO{pin}: {e}", file=sys.stderr)
            raise

    def on(self):
        if self.device is not None:
            self.device.on()

    def off(self):
        if self.device is not None:
            self.device.off()

    def close(self):
        if self.device is not None:
            try:
                self.device.close()
            except DeviceClosed:
                pass
            except GPIOZeroError as e:
                print(f"Error closing laser GPIO{self.pin}: {e}", file=sys.stderr)
            finally:
                self.device = None


class Aim:
    """Controls a laser and two servos to aim at targets."""

    def __init__(self, ld=0.5, sd=0.5):
        self.ld = ld
        self.sd = sd
        self.hp = [0.0] * 10
        self.vp = [0.0] * 10
        self.laser_delay = ld
        self.short_delay = sd

        # Map pulse widths to servo positions (0.0 to 1.0)
        for i in range(10):
            self.hp[i] = HORIZONTAL_PULSE_WIDTHS[i]
            self.vp[i] = VERTICAL_PULSE_WIDTHS[i]

        self.laser = Laser()
        self.horizontal = None
        self.vertical = None
        try:
            self.horizontal = Servo(HORIZONTAL_PIN, min_pulse_width=0.0005, max_pulse_width=0.0025)
            self.vertical = Servo(VERTICAL_PIN, min_pulse_width=0.0005, max_pulse_width=0.0025)
        except GPIOZeroError as e:
            print(f"Error initializing servos: {e}", file=sys.stderr)
            self.laser.close()
            raise

    def aim(self, nums):
        """Aim at a list of targets (1-based indices)."""
        try:
            for b in nums:
                if not _running:
                    break
                self.horizontal.value = self.hp[b - 1]
                self.vertical.value = self.vp[b - 1]
                self.laser.on()
                time.sleep(self.laser_delay)
                self.laser.off()
                self.horizontal.value = self.hp[9]
                self.vertical.value = self.vp[9]
                time.sleep(self.short_delay)
            self.laser.off()
        except DeviceClosed as e:
            print(f"Device closed during aim: {e}", file=sys.stderr)
        except GPIOZeroError as e:
            print(f"GPIO error during aim: {e}", file=sys.stderr)

    def cleanup(self):
        """Release all resources cleanly."""
        self.laser.off()
        self.laser.close()
        if self.horizontal is not None:
            try:
                self.horizontal.close()
            except DeviceClosed:
                pass
        if self.vertical is not None:
            try:
                self.vertical.close()
            except DeviceClosed:
                pass


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    aim_system = None
    try:
        aim_system = Aim(ld=0.5, sd=0.5)
        aim_system.aim([1, 2, 3])
    except GPIOZeroError as e:
        print(f"Fatal GPIO error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if aim_system is not None:
            aim_system.cleanup()


if __name__ == "__main__":
    main()

