import serial
import time
import logging
import signal
import sys
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class GSMModule:
    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=2, power_pin=4):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.power_pin = power_pin
        self.ser = None
        self._running = True
        self._install_signal_handlers()

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.power_pin, GPIO.OUT, initial=GPIO.LOW)
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            raise

        self._power_on_module()
        self._open_serial_port()

    def _install_signal_handlers(self):
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, self._signal_handler)

    def _signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received, shutting down.")
        self._running = False
        self.close()
        sys.exit(0)

    def _power_on_module(self):
        try:
            GPIO.output(self.power_pin, GPIO.HIGH)
            time.sleep(2)
            logging.info("GSM module powered on.")
        except Exception as e:
            logging.error(f"Failed to power on module: {e}")
            raise

    def _open_serial_port(self):
        try:
            self.ser = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                timeout=self.timeout
            )
            logging.info(f"Serial port {self.port} opened at {self.baudrate} baud.")
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            self._cleanup_gpio()
            raise

    def _send_at_command(self, command, attempts=5, wait=0.1):
        if self.ser is None or not self.ser.is_open:
            logging.error("Serial port is not open.")
            return None

        try:
            self.ser.reset_input_buffer()
            self.ser.write((command + '\r\n').encode('utf-8'))
            time.sleep(wait)
            response = self.read_response(attempts=attempts)
            if response is None:
                logging.warning(f"No response to command: {command}")
                return None
            if 'OK' in response or 'OK\r\n' in response:
                return response
            if 'ERROR' in response or 'ERROR\r\n' in response:
                logging.error(f"Command {command} failed with ERROR.")
                return None
            logging.warning(f"Unexpected response to {command}: {response}")
            return None
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error sending command: {e}")
            return None

    def read_response(self, attempts=5):
        if self.ser is None or not self.ser.is_open:
            return None

        response = b''
        for _ in range(attempts):
            try:
                chunk = self.ser.read(1024)
                if chunk:
                    response += chunk
                    if b'OK' in response or b'ERROR' in response or b'+CMTI' in response:
                        break
            except serial.SerialException as e:
                logging.error(f"Serial read error: {e}")
                return None
            except Exception as e:
                logging.error(f"Unexpected read error: {e}")
                return None
            time.sleep(0.05)

        if not response:
            return None

        try:
            return response.decode('utf-8', errors='replace')
        except Exception as e:
            logging.error(f"Failed to decode response: {e}")
            return None

    def send_tcp_data(self, data, ip='192.168.100.12', port=50):
        if self.ser is None or not self.ser.is_open:
            logging.error("Serial port is not open.")
            return False

        logging.info(f"Sending TCP data to {ip}:{port}")
        if not self._send_at_command(f'AT+CIPSTART="TCP","{ip}",{port}'):
            logging.error("Failed to start TCP connection.")
            return False

        if not self._send_at_command('AT+CIPSEND'):
            logging.error("Failed to initiate data send.")
            self._send_at_command('AT+CIPCLOSE')
            return False

        try:
            self.ser.write(data.encode('utf-8'))
            self.ser.write(b'\x1A')
            time.sleep(0.5)
            response = self.read_response(attempts=10)
            if response and 'SEND OK' in response:
                logging.info("Data sent successfully.")
                if not self._send_at_command('AT+CIPCLOSE'):
                    logging.warning("Failed to close connection cleanly.")
                return True
            else:
                logging.error(f"Failed to send data. Response: {response}")
                self._send_at_command('AT+CIPCLOSE')
                return False
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            self._send_at_command('AT+CIPCLOSE')
            return False
        except Exception as e:
