    global _running
    _running = False

def initialize_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(PUMP_GPIO_PIN, GPIO.OUT, initial=GPIO.LOW)

def initialize_i2c():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_soil_sensor(i2c_bus):
    try:
        sensor = adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=I2C_ADDRESS)
        return sensor
    except Exception as e:
        print(f"Error initializing soil moisture sensor at 0x{I2C_ADDRESS:02X}: {e}")
        return None

def read_soil_moisture(sensor):
    try:
        return sensor.moisture_read()
    except Exception as e:
        print(f"Error reading soil moisture: {e}")
        return None

def control_water_pump(moisture_level):
    if moisture_level is None:
        print("Moisture level is None. Turning pump OFF for safety.")
        GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)
        return "UNKNOWN"
    if moisture_level < DRY_SOIL_THRESHOLD:
        GPIO.output(PUMP_GPIO_PIN, GPIO.HIGH)
        return "ON"
    else:
        GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)
        return "OFF"

def cleanup():
    print("Cleaning up GPIO and exiting.")
    GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)
    GPIO.cleanup()

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    initialize_gpio()

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        cleanup()
        sys.exit(1)

    soil_sensor = initialize_soil_sensor(i2c_bus)
    if soil_sensor is None:
        cleanup()
        sys.exit(1)

    try:
        while _running:
            moisture_level = read_soil_moisture(soil_sensor)
            pump_status = control_water_pump(moisture_level)

            if moisture_level is not None:
                print(f"Soil Moisture: {moisture_level}, Pump: {pump_status}")
            else:
                print(f"Soil Moisture: READ ERROR, Pump: {pump_status}")

            # Sleep in small increments to allow prompt signal handling
            slept = 0
            while _running and slept < READ_INTERVAL_SECONDS:
                time.sleep(0.5)
                slept += 0.5
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

