import signal
import sys
from flask import Flask, request, jsonify
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

app = Flask(__name__)

RELAY_PIN = 23
relay = None

@app.route('/relay', methods=['POST'])
def relay_control():
    """Handle POST requests to control the relay state."""
    try:
        request_data = request.get_json(silent=True)
        if not request_data or 'state' not in request_data:
            return jsonify({'error': 'Invalid request'}), 400

        relay_state = request_data['state']
        if relay_state not in ('on', 'off'):
            return jsonify({'error': 'Invalid request'}), 400

        if relay_state == 'on':
            relay.on()
        else:
            relay.off()

        return jsonify({'status': 'Relay state changed'})

    except (TypeError, ValueError) as e:
        print(f"Error processing request: {e}", file=sys.stderr)
        return jsonify({'error': 'Invalid request'}), 400

def cleanup(signum=None, frame=None):
    """Clean up GPIO resources on exit."""
    global relay
    if relay is not None:
        try:
            relay.close()
        except Exception as e:
            print(f"Error closing relay: {e}", file=sys.stderr)
        relay = None
    if signum is not None:
        sys.exit(0)

if __name__ == '__main__':
    try:
        relay = OutputDevice(RELAY_PIN)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO{RELAY_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        app.run(host='0.0.0.0', port=5000)
    finally:
        cleanup()

