import signal
import sys
from gpiozero import OutputDevice

# BCM GPIO20 -> nutrient pump, BCM GPIO21 -> grow light
PUMP_PIN = 20
LIGHT_PIN = 21

# Global references for safe shutdown
pump = None
light = None


def parse_intent(phrase):
    """Return the normalized intent keyword extracted from a phrase."""
    keywords = {
        "pump_on": ["pump", "nutrient", "on"],
        "pump_off": ["pump", "nutrient", "off"],
        "light_toggle": ["light", "grow", "toggle"],
    }
    for intent, kws in keywords.items():
        if any(kw in phrase.lower() for kw in kws):
            return intent
    return None


def apply_intent(intent):
    """Drive the appropriate gpiozero OutputDevice based on the intent."""
    if intent == "pump_on":
        pump.on()
        print("Nutrient pump turned ON")
    elif intent == "pump_off":
        pump.off()
        print("Nutrient pump turned OFF")
    elif intent == "light_toggle":
        light.toggle()
        state = "ON" if light.is_active else "OFF"
        print(f"Grow light toggled -> {state}")


def cleanup():
    """Turn off and close every actuator so they are safe on exit."""
    global pump, light
    for dev in (pump, light):
        if dev is not None:
            try:
                dev.off()
                dev.close()
            except Exception:
                pass
    print("Actuators shut down safely")


def main():
    global pump, light
    try:
        pump = OutputDevice(PUMP_PIN)
        light = OutputDevice(LIGHT_PIN)
    except Exception as exc:
        print(f"Failed to initialize GPIO devices: {exc}")
        sys.exit(1)

    test_phrases = [
        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command",
    ]

    try:
        for phrase in test_phrases:
            intent = parse_intent(phrase)
            if intent:
                apply_intent(intent)
            else:
                print(f"Unknown command: {phrase}")
            print("-" * 40)
    except KeyboardInterrupt:
        print("\nInterrupted by user")
    except Exception as exc:
        print(f"Runtime error: {exc}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

