import time
import signal
import sys
from gpiozero import OutputDevice

class AimingController:
    SERVOBLASTER_PATH = "/dev/servoblaster"
    LASER_PIN = 17

    def __init__(self, ld=0.5, hd=1.0):
        self.ld = ld
        self.hd = hd
        self.hx = [133, 128, 122, 133, 128, 122, 133, 128, 122, 128]
        self.vy = [75, 75, 75, 72, 72, 72, 68, 68, 68, 90]
        self.laser = None
        self._servoblaster = None
        self._install_signal_handlers()
        self._init_laser()

    def _install_signal_handlers(self):
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, self._signal_handler)

    def _signal_handler(self, signum, frame):
        self._cleanup()
        sys.exit(0)

    def _init_laser(self):
        try:
            self.laser = OutputDevice(self.LASER_PIN, active_high=True, initial_value=False)
        except Exception as e:
            print(f"Error initializing laser on GPIO{self.LASER_PIN}: {e}")
            self.laser = None

    def _cleanup(self):
        if self.laser is not None:
            try:
                self.laser.off()
            except Exception:
                pass
            try:
                self.laser.close()
            except Exception:
                pass
            self.laser = None

    def aim_blocks(self, nums):
        if self.laser is None:
            print("Laser not initialized; cannot aim.")
            return
        try:
            self._servoblaster = open(self.SERVOBLASTER_PATH, "w")
        except Exception as e:
            print(f"Error opening {self.SERVOBLASTER_PATH}: {e}")
            self._cleanup()
            return

