class ESP8266:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.serial = None
        self._running = True
        try:
            self.serial = serial.Serial(
                port=port,
                baudrate=baud_rate,
                timeout=timeout
            )
            print(f"ESP8266 initialized on {port} at {baud_rate} baud.")
        except serial.SerialException as e:
            print(f"Error initializing serial port {port}: {e}")
            self.serial = None

    def _send_command(self, command, timeout=1.0, wait_for=b'OK'):
        if not self.serial or not self.serial.is_open:
            print("Serial port not open.")
            return None
        try:
            self.serial.reset_input_buffer()
            self.serial.write(command.encode('utf-8'))
