import sys
import time
import signal
import serial
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    alarm = None
    ser = None

    try:
        try:
            alarm = OutputDevice(ALARM_PIN)
        except Exception as e:
            print(f"Error: failed to initialize GPIO {ALARM_PIN}: {e}", file=sys.stderr)
            sys.exit(1)

        try:
            ser = serial.Serial(
                port=SERIAL_PORT,
                baudrate=BAUD_RATE,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0
            )
        except serial.SerialException as e:
            print(f"Error: cannot open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
            sys.exit(1)

        print(f"Listening on {SERIAL_PORT} @ {BAUD_RATE} baud. Press Ctrl+C to stop.")

        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Warning: serial read error: {e}", file=sys.stderr)
                time.sleep(READ_INTERVAL)
                continue

            if not raw:
                time.sleep(READ_INTERVAL)
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                time.sleep(READ_INTERVAL)
                continue

            try:
                radiation = float(line)
            except ValueError:
                print(f"Warning: non-numeric data received: {line!r}", file=sys.stderr)
                time.sleep(READ_INTERVAL)
                continue

            print(f"Radiation Level: {radiation:.2f} µSv/h")

            try:
                if radiation > RADIATION_THRESHOLD:
                    alarm.on()
                else:
                    alarm.off()
            except Exception as e:
                print(f"Warning: GPIO write failed: {e}", file=sys.stderr)

            time.sleep(READ_INTERVAL)

    finally:
        if ser is not None and ser.is_open:
            try:
                ser.close()
            except Exception:
                pass
        if alarm is not None:
            try:
                alarm.close()
            except Exception:
                pass
        print("Resources released. Exiting.")

if __name__ == '__main__':
    main()

