            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=SERIAL_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error opening serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None


def parse_radiation_level(raw):
    if not raw:
        return None
    try:
        return float(raw)
    except ValueError:
        return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    alarm = OutputDevice(ALARM_PIN, active_high=True, initial_value=False)
    alarm_state = False

    try:
        while _running:
            try:
                raw_line = ser.readline()
            except serial.SerialException as exc:
                print(f"Serial I/O error: {exc}", file=sys.stderr)
                time.sleep(READ_INTERVAL)
                continue

            if not raw_line:
                time.sleep(READ_INTERVAL)
                continue

            try:
                line = raw_line.decode('ascii', errors='replace').strip()
            except Exception as exc:
                print(f"Decode error: {exc}", file=sys.stderr)
                time.sleep(READ_INTERVAL)
                continue

            if not line:
                time.sleep(READ_INTERVAL)
                continue

            radiation = parse_radiation_level(line)
            if radiation is None:
                print(f"Invalid data received: {line!r}")
                time.sleep(READ_INTERVAL)
                continue

            print(f"Radiation Level: {radiation:.2f} uSv/h")

            if radiation > RADIATION_THRESHOLD:
                if not alarm_state:
                    alarm.on()
                    alarm_state = True
                    print("ALARM ACTIVATED: Radiation level exceeded threshold!")
            else:
                if alarm_state:
                    alarm.off()
                    alarm_state = False
                    print("ALARM DEACTIVATED: Radiation level is normal.")

            time.sleep(READ_INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        try:
            alarm.close()
        except Exception:
            pass
        print("Resources released. Exiting.")


if __name__ == "__main__":
    main()

