import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'co2_readings_log.txt'
SAMPLE_INTERVAL = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_co2_level(serial_connection):
    try:
        raw = serial_connection.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    if not raw:
        return None
    data = raw.decode('ascii', errors='replace').strip()
    if not data:
        return None
    try:
        return int(data)
    except ValueError:
        print(f"Invalid data received (not numeric): {data!r}", file=sys.stderr)
        return None

def log_co2_level(log_file, timestamp, co2_level):
    try:
        log_file.write(f"{timestamp}, {co2_level}\n")
        log_file.flush()
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        sys.exit(1)

    log_file = None
    try:
        log_file = open(LOG_FILE, 'a', encoding='utf-8')
        while _running:
            co2_level = read_co2_level(serial_connection)
            if co2_level is not None:
                timestamp = datetime.now().isoformat(timespec='seconds')
                log_co2_level(log_file, timestamp, co2_level)
                print(f"CO2 Level: {co2_level} ppm")
            time.sleep(SAMPLE_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
        if log_file:
            log_file.close()
        print("Program terminated.")

if __name__ == "__main__":
    main()

