    Returns a dict with keys 'latitude', 'longitude', 'altitude' or None if parsing fails.
    """
    if not data.startswith('$GPGGA'):
        return None

    parts = data.split(',')
    if len(parts) < 10:
        return None

    # Check if GPS fix is valid (fix quality indicator = 1)
    if parts[6] != '1':
        return None

    try:
        latitude = decode_coordinate(parts[2], parts[3])
        longitude = decode_coordinate(parts[4], parts[5])
        altitude = float(parts[9]) if parts[9] else None
        return {'latitude': latitude, 'longitude': longitude, 'altitude': altitude}
    except (ValueError, IndexError):
        return None

def decode_coordinate(coordinate, direction):
    """Decodes the GPS coordinate format (ddmm.mmmm) to decimal degrees."""
    if not coordinate or not direction:
        return None
    try:
        degrees = int(coordinate[:-2])
        minutes = float(coordinate[-2:])
        decimal_degrees = degrees + (minutes / 60.0)
        if direction in ('S', 'W'):
            decimal_degrees = -decimal_degrees
        return decimal_degrees
    except ValueError:
        return None

def log_coordinates(coordinates, log_file):
    """Logs the coordinates with an ISO 8601 timestamp to the specified log file."""
    if not coordinates:
        return

    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    log_entry = f"{timestamp} - Latitude: {coordinates['latitude']}, Longitude: {coordinates['longitude']}, Altitude: {coordinates['altitude']}\n"

