            raise ValueError(f'Heart rate {heart_rate} out of range')
        if not (0 <= spo2 <= 100):
            raise ValueError(f'SpO2 {spo2} out of range')
        print(f'Heart Rate: {heart_rate} bpm, SpO2: {spo2} %')
        log_data(heart_rate, spo2)
    except ValueError as e:
        print(f'Error parsing data: {e} - Raw: {raw_data}', file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f'Connected to {SERIAL_PORT} at {BAUD_RATE} baud.')
            while _running:
                try:
                    raw_bytes = ser.readline()
                    if not raw_bytes:
                        continue
                    raw_data = raw_bytes.decode('ascii', errors='replace').strip()
                    if raw_data:
                        process_data(raw_data)
