import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional, Tuple

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

@dataclass
class GPS_readings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellites: Optional[int] = None

class GPSReader:
    def __init__(self, port: str = '/dev/serial0', baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port: Optional[serial.Serial] = None
        self._connected = False

    def connect(self) -> bool:
        if self._connected:
            logging.warning("Already connected to GPS serial port.")
            return True
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout
            )
            self._connected = True
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to connect to GPS on {self.port}: {e}")
            self.serial_port = None
            self._connected = False
            return False
        except Exception as e:
            logging.error(f"Unexpected error opening serial port {self.port}: {e}")
            self.serial_port = None
            self._connected = False
            return False

    def disconnect(self) -> None:
        if not self._connected:
            logging.info("GPS already disconnected.")
            return
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                logging.info("GPS serial port closed.")
            except Exception as e:
                logging.error(f"Error closing serial port: {e}")
            finally:
                self.serial_port = None
                self._connected = False
        else:
            logging.warning("Attempted to disconnect but serial port was None.")

    def _verify_checksum(self, sentence: str) -> bool:
        if '*' not in sentence:
            return False
        body, _, csum = sentence.partition('*')
        if not body.startswith('$'):
            return False
        body = body[1:]
        try:
            expected = int(csum.strip(), 16)
        except ValueError:
            return False
        computed = 0
        for ch in body:
            computed ^= ord(ch)
        return computed == expected

    def _parse_gpgga(self, sentence: str) -> Optional[GPS_readings]:
        if not sentence.startswith('$GPGGA'):
            return None
        if not self._verify_checksum(sentence):
            logging.warning("Checksum verification failed for GPGGA sentence.")
            return None
        fields = sentence.split(',')
        if len(fields) < 15:
            logging.warning("GPGGA sentence has insufficient fields.")
            return None
        try:
            fix_quality = int(fields[6])
            if fix_quality == 0:
                logging.debug("No GPS fix (fix_quality=0).")
                return None
            latitude = self._nmea_to_decimal(fields[2], fields[3])
            longitude = self._nmea_to_decimal(fields[4], fields[5])
            altitude = float(fields[9]) if fields[9] else None
            satellites = int(fields[7]) if fields[7] else None
            return GPS_readings(
                latitude=latitude,
                longitude=longitude,
                altitude=altitude,
                satellites=satellites
            )
        except (ValueError, IndexError) as e:
            logging.error(f"Error parsing GPGGA sentence: {e}")
            return None

    @staticmethod
    def _nmea_to_decimal(value: str, direction: str) -> Optional[float]:
        if not value or not direction:
            return None
        try:
            dot = value.index('.')
            deg_len = dot - 2
            degrees = float(value[:deg_len])
            minutes = float(value[deg_len:])
            decimal = degrees + minutes / 60.0
            if direction in ('S', 'W'):
                decimal = -decimal
            return decimal
        except (ValueError, IndexError) as e:
            logging.error(f"Error converting NMEA coordinate: {e}")
            return None

    def read(self) -> Optional[GPS_readings]:
        if not self._connected or self.serial_port is None:
            logging.warning("Serial port not connected. Call connect() first.")
            return None
        try:
            raw = self.serial_port.readline()
            if not raw:
                logging.warning("Read timeout: no data received.")
                return None
            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                return None
            return self._parse_gpgga(line)
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            self.disconnect()
            return None
        except Exception as e:
            logging.error(f"Unexpected error reading GPS data: {e}")
            return None

def main():
    gps = GPSReader(port='/dev/serial0', baudrate=9600, timeout=1.0)
    running = True

    def signal_handler(signum, frame):
        nonlocal running
        logging.info(f"Signal {signum} received, shutting down...")
        running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not gps.connect():
        logging.error("Failed to connect to GPS. Exiting.")
        sys.exit(1)

    try:
        while running:
            readings = gps.read()
            if readings is not None:
                logging.info(
                    f"Lat={readings.latitude}, Lon={readings.longitude}, "
                    f"Alt={readings.altitude}, Sat={readings.satellites}"
                )
    finally:
        gps.disconnect()
        logging.info("GPSReader stopped.")

if __name__ == '__main__':
    main()

