import signal
import threading
import time
from flask import Flask, jsonify, request, Response
import serial
import serial.tools.list_ports

app = Flask(__name__)

# ---------------------------------------------------------------------------
# Serial communicator
# ---------------------------------------------------------------------------
class SerialCommunicator:
    """Thread-safe serial port wrapper with context-manager support."""

    def __init__(self, port: str = '/dev/ttyUSB0', baudrate: int = 9600):
        self.port = port
        self.baudrate = baudrate
        self.ser: serial.Serial | None = None
        self._lock = threading.Lock()

    # -- context manager -----------------------------------------------------
    def __enter__(self):
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()
        return False

    # -- lifecycle -----------------------------------------------------------
    def open(self) -> None:
        """Open the serial port, raising on failure."""
        with self._lock:
            if self.ser is not None and self.ser.is_open:
                return
            try:
                self.ser = serial.Serial(
                    port=self.port,
                    baudrate=self.baudrate,
                    bytesize=serial.EIGHTBITS,
                    parity=serial.PARITY_NONE,
                    stopbits=serial.STOPBITS_ONE,
                    timeout=1.0,
                    write_timeout=1.0,
                )
                if not self.ser.is_open:
                    raise serial.SerialException(f"Failed to open {self.port}")
            except serial.SerialException as exc:
                self.ser = None
                raise

    def close(self) -> None:
        """Idempotently close the serial port."""
        with self._lock:
            if self.ser is not None:
                try:
                    if self.ser.is_open:
                        self.ser.close()
                except serial.SerialException:
                    pass
                finally:
                    self.ser = None

    # -- I/O -----------------------------------------------------------------
    def send(self, command: str) -> int:
        """Send a command string; return the number of bytes written."""
        if not self.ser or not self.ser.is_open:
            raise serial.SerialException("Serial port is not open")
        data = command.encode('ascii', errors='replace')
        written = self.ser.write(data)
        if written is None or written != len(data):
            raise serial.SerialException(
                f"Short write: {written}/{len(data)} bytes"
            )
        self.ser.flush()
        return written

    def receive_line(self) -> str | None:
        """Read one line (up to newline) with a 1-second timeout.

        Returns the stripped string, or None on timeout / error.
        """
        if not self.ser or not self.ser.is_open:
            return None
        try:
            raw = self.ser.readline()
        except serial.SerialException:
            return None
        if not raw:
            return None  # timeout
        return raw.decode('ascii', errors='replace').strip()


# ---------------------------------------------------------------------------
# Data manager
# ---------------------------------------------------------------------------
class DataManager:
    """Thread-safe in-memory data store."""

    def __init__(self):
        self.data_store = [
            {'id': 1, 'name': 'Item 1', 'done': False},
            {'id': 2, 'name': 'Item 2', 'done': True},
        ]
        self._lock = threading.Lock()

    def get_all(self):
        with self._lock:
            return list(self.data_store)

    def get_by_id(self, item_id: int):
        with self._lock:
            for item in self.data_store:
                if item['id'] == item_id:
                    return item
            return None

    def create(self, name: str, done: bool):
        """Create a new item; return the item or None on validation error."""
        if not name or not isinstance(name, str):
            return None
        if not isinstance(done, bool):
            return None
        with self._lock:
            new_id = (self.data_store[-1]['id'] + 1) if self.data_store else 1
            item = {'id': new_id, 'name': name, 'done': done}
            self.data_store.append(item)
            return item


# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
SERIAL_PORT = SerialCommunicator('/dev/ttyUSB0', 9600)
DATA_MANAGER = DataManager()
_shutdown = threading.Event()


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    print(f"\nReceived signal {signum}, shutting down...")
    _shutdown.set()


# ---------------------------------------------------------------------------
# Routes
# ---------------------------------------------------------------------------
@app.route('/version', methods=['GET'])
def get_device_version():
    """Query the connected device with *IDN? and return its response."""
    try:
        with SERIAL_PORT as port:
            port.send('*IDN?\n')
            response = port.receive_line()
            if response is None:
                return Response(
                    "No response from device (timeout).",
                    status=504,
                    mimetype='text/plain',
                )
            return Response(response, mimetype='text/plain')
    except serial.SerialException as exc:
        print(f"Serial error: {exc}")
        return Response(str(exc), status=502, mimetype='text/plain')
    except Exception as exc:
        print(f"Unexpected error: {exc}")
        return Response(str(exc), status=500, mimetype='text/plain')


@app.route('/data', methods=['GET'])
def get_all_data():
    items = DATA_MANAGER.get_all()
    return jsonify(items)


@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_by_id(item_id: int):
    item = DATA_MANAGER.get_by_id(item_id)
    if item:
        return jsonify(item)
    return Response("Item not found", status=404, mimetype='text/plain')


@app.route('/data', methods=['POST'])
def create_data():
    """Create a new data item from JSON request body."""
    request_data = request.get_json(silent=True)
    if not request_data:
        return Response("Invalid JSON", status=400, mimetype='text/plain')
    name = request_data.get('name')
    done = request_data.get('done', False)
    item = DATA_MANAGER.create(name, done)
    if item:
