import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def parse_oximeter_data(data):
    parts = data.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected 2 fields, got {len(parts)}: {data!r}")
    heart_rate, spo2 = parts
    return int(heart_rate), int(spo2)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                heart_rate, spo2 = parse_oximeter_data(line)
                print(f'Heart Rate: {heart_rate} bpm, SpO2: {spo2} %')
            except ValueError as e:
                print(f"Warning: invalid data format '{line}': {e}", file=sys.stderr)

            time.sleep(1)
    finally:
        if ser.is_open:
            ser.close()
        print("Serial port closed. Exiting.")

if __name__ == '__main__':
    main()

