from flask import Flask, Response, request, jsonify
import serial
import time
import json
import threading

app = Flask(__name__)

data_store = [
    {'id': 1, 'name': 'Item 1', 'done': False},
    {'id': 2, 'name': 'Item 2', 'done': False},
]

lock = threading.Lock()


def get_serial_version():
    """Open /dev/ttyUSB0 at 9600 baud, send *IDN?\n, read response, close."""
    ser = None
    try:
        ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
        ser.write(b'*IDN?\n')
        time.sleep(0.1)
        raw = ser.read(ser.in_waiting or 1024)
        if not raw:
            return Response('No response from device', status=503, mimetype='text/html')
        return Response(raw.decode(errors='replace').replace('\n', '<br>'), mimetype='text/html')
    except serial.SerialException as e:
        return Response(f'Serial error: {e}', status=503, mimetype='text/html')
    except Exception as e:
        return Response(f'Unexpected error: {e}', status=503, mimetype='text/html')
    finally:
        if ser is not None and ser.is_open:
            ser.close()


@app.route('/version')
def version():
    return get_serial_version()


@app.route('/getdata')
def get_data():
    with lock:
        return jsonify(data_store)


@app.route('/getset/<int:item_id>')
def get_set_item(item_id):
    with lock:
        item = next((it for it in data_store if it['id'] == item_id), None)
        if item is not None:
            return jsonify(item)
        return jsonify({'error': 'Item not found'}), 404


@app.route('/getpost/<int:item_id>/<name>')
def get_post_item(item_id, name):
    new_item = {'id': item_id, 'name': name, 'done': False}
    with lock:
        data_store.append(new_item)
        return jsonify(data_store)


@app.route('/postjson', methods=['POST'])
def post_json():
    if request.is_json:
        try:
            content = request.get_json()
        except Exception:
            return jsonify({'error': 'Invalid JSON'}), 400
    else:
        content = request.form
    try:
        new_item = {
            'id': int(content.get('id', len(data_store) + 1)),
            'name': content.get('name', ''),
            'done': content.get('done', 'False').lower() in ('true', '1', 'yes')
        }
    except (ValueError, AttributeError, TypeError):
        return jsonify({'error': 'Invalid input data'}), 400
    with lock:
        data_store.append(new_item)
        return jsonify(data_store)


@app.route('/postjson')
def get_json():
    with lock:
        return jsonify(data_store)


if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0')

