import serial
import time
import sys

BLUETOOTH_PORT = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400


def send_command(ser, command):
    """Sends a command to the Bluetooth device with error handling."""
    try:
        full_command = f"X{command}\n"
        ser.write(full_command.encode("utf-8"))
        ser.flush()
        time.sleep(0.1)
    except serial.SerialException as e:
        raise RuntimeError(f"Error sending command: {e}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error during command transmission: {e}")


def main():
    """Main function to handle user input and send commands."""
    ser = None
    try:
        ser = serial.Serial(BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE, timeout=1)
        print(f"Connected to {BLUETOOTH_PORT} at {BLUETOOTH_BAUD_RATE} baud.")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.lower() == "exit":
                print("Exiting...")
                break

            try:
                send_command(ser, user_command)
                print(f"Sent: {user_command}")
            except RuntimeError as e:
                print(f"Error: {e}")
                break

    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

